insert into public.quest_templates (id, source, ability, difficulty, periods, title, flavor, objective, tips, validation, tags, is_active) values
('for-easy-le-salut-du-forgeron', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Le Salut du Forgeron', 'Avant d’allumer la forge, le forgeron éveille ses bras. Fais de même avant que la journée ne t’emporte.', 'Faire 20 pompes (sur les genoux autorisé), en une ou plusieurs séries.', array['Mieux vaut cinq séries propres qu’une série bâclée.', 'Expire en poussant, inspire en descendant.']::text[], '{"type":"counter","target":20,"unit":"pompes"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('for-easy-l-echauffement-du-soldat', 'catalog', 'FOR', 'easy', array['daily']::text[], 'L’Échauffement du Soldat', 'Le soldat qui s’échauffe ne boite pas à la première marche. Tes jambes t’en remercieront.', 'Faire 30 squats, dos droit, talons au sol.', array['Imagine que tu t’assois sur une chaise derrière toi.', 'Descends moins bas si tes genoux tirent.']::text[], '{"type":"counter","target":30,"unit":"squats"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('for-easy-la-garde-du-rempart', 'catalog', 'FOR', 'easy', array['daily']::text[], 'La Garde du Rempart', 'La sentinelle ne bouge pas, mais elle ne s’effondre pas non plus. Tenir est un art.', 'Tenir 1 minute de gainage (planche) au total, en une ou plusieurs fois.', array['Les coudes sous les épaules, le corps droit comme une lance.', 'Fractionne en 3 × 20 secondes si besoin.']::text[], '{"type":"timer","minutes":1}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('for-easy-les-marches-du-beffroi', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Les Marches du Beffroi', 'Les cloches sonnent mieux pour ceux qui ont gravi la tour. L’ascenseur est une facilité de roi.', 'Prendre les escaliers pour au moins 3 étages, au lieu de l’ascenseur.', array['Garde un rythme régulier, sans te presser.', 'Pas d’escaliers ? Une côte ou un trottoir en pente fait l’affaire.']::text[], '{"type":"simple"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('for-easy-le-reveil-de-la-forteresse', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Le Réveil de la Forteresse', 'Une forteresse bien gardée commence par des fondations solides. Les tiennes passent par le ventre.', 'Faire 3 séries de 10 abdominaux ou relevés de jambes.', array['Ne tire pas sur la nuque : les mains près des tempes.', 'Souffle pendant l’effort.']::text[], '{"type":"counter","target":30,"unit":"répétitions"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('for-easy-la-bravade-du-matin', 'catalog', 'FOR', 'easy', array['daily']::text[], 'La Bravade du Matin', 'Les gardes du nord se lavent à l’eau du torrent. Ils disent que la peur fond avant la glace.', 'Terminer ta douche par 30 secondes d’eau fraîche, si ta santé le permet.', array['Respire lentement : l’expiration longue calme le choc.', 'Commence par les jambes, puis remonte.']::text[], '{"type":"simple"}'::jsonb, array['sans matériel', 'défi']::text[], true),
('for-easy-le-non-du-rempart', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Le Non du Rempart', 'Une porte qui ne se ferme jamais n’est plus une porte. Savoir refuser protège ce qui compte.', 'Refuser poliment une demande ou une invitation dont tu n’as pas envie.', array['Une phrase courte suffit : « Merci, mais ce n’est pas possible pour moi. »', 'Pas besoin de te justifier longuement.']::text[], '{"type":"simple"}'::jsonb, array['social', 'sans matériel']::text[], true),
('for-easy-le-pas-de-cote', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Le Pas de Côté', 'Le voyageur qui quitte la grand-route découvre des chemins que personne ne lui avait montrés.', 'Essayer une petite nouveauté : un autre trajet, un plat, un rayon, un morceau inconnu.', array['Cela doit être nouveau pour toi, pas spectaculaire.', 'Note ce que tu as ressenti en une phrase.']::text[], '{"type":"simple"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('for-easy-la-charge-du-porteur', 'catalog', 'FOR', 'easy', array['daily']::text[], 'La Charge du Porteur', 'Les caravanes ne traversent pas les cols toutes seules. Quelqu’un porte les vivres.', 'Faire 10 soulevés de charge (sac chargé de livres, packs d’eau) en gardant le dos droit.', array['Fléchis les genoux, pas le dos.', 'Choisis une charge qui reste confortable.']::text[], '{"type":"counter","target":10,"unit":"soulevés"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('for-easy-le-cheval-de-bois', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Le Cheval de Bois', 'Le cavalier novice apprend d’abord sur un cheval qui ne bouge pas. Ses cuisses s’en souviennent.', 'Tenir 30 secondes en position de chaise contre un mur, deux fois.', array['Les cuisses parallèles au sol si possible.', 'Respire, ne retiens pas ton souffle.']::text[], '{"type":"counter","target":2,"unit":"séries"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('for-easy-la-parole-franche', 'catalog', 'FOR', 'easy', array['daily']::text[], 'La Parole Franche', 'Le héraut n’étouffe pas les mauvaises nouvelles. Il les annonce avec respect, et le royaume s’en porte mieux.', 'Dire à quelqu’un une chose vraie mais difficile, avec bienveillance.', array['Parle de ce que tu ressens, pas de ce qu’il est.', 'Choisis un moment calme.']::text[], '{"type":"simple"}'::jsonb, array['social', 'sans matériel']::text[], true),
('for-easy-les-fentes-du-chevalier', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Les Fentes du Chevalier', 'Le chevalier avance toujours d’un pied ferme. Mille fentes ont précédé son premier tournoi.', 'Faire 20 fentes (10 par jambe), buste droit.', array['Le genou avant ne dépasse pas la pointe du pied.', 'Appuie-toi sur un mur si l’équilibre manque.']::text[], '{"type":"counter","target":20,"unit":"fentes"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('for-easy-le-pas-redouble', 'catalog', 'FOR', 'easy', array['daily']::text[], 'Le Pas Redoublé', 'Le tambour bat la cadence. Ceux qui suivent le rythme arrivent plus loin qu’ils ne l’espéraient.', 'Faire 3 fois 1 minute de jumping jacks ou de montées de genoux, avec 30 secondes de pause.', array['Garde un rythme que tu peux tenir.', 'Les bras suivent le mouvement des jambes.']::text[], '{"type":"counter","target":3,"unit":"séries"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('for-easy-la-poignee-de-fer', 'catalog', 'FOR', 'easy', array['daily']::text[], 'La Poignée de Fer', 'La poignée de main d’un chef de guilde vaut un contrat. La tienne en dit plus que ta carte de visite.', 'Serrer un objet (balle, serviette roulée) 20 fois par main, ou tenir 30 secondes de suspension à une barre.', array['Contracte fort, relâche complètement.', 'Arrête-toi si tu sens une douleur vive.']::text[], '{"type":"simple"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('for-medium-le-fardeau-du-porteur', 'catalog', 'FOR', 'medium', array['daily', 'weekly']::text[], 'Le Fardeau du Porteur', 'Les caravanes ne traversent pas les cols toutes seules. Aujourd’hui, c’est toi qui portes les vivres.', 'Faire une séance de renforcement de 30 minutes : pompes, squats, gainage, fentes.', array['Alterne les exercices pour ne pas te lasser.', 'Un échauffement de 3 minutes avant, des étirements après.']::text[], '{"type":"timer","minutes":30}'::jsonb, array['sans matériel', 'sport']::text[], true),
('for-medium-le-cercle-du-gymnaste', 'catalog', 'FOR', 'medium', array['daily', 'weekly']::text[], 'Le Cercle du Gymnaste', 'Dans la cour des gardes, on s’entraîne sans salle ni armure. Le sol et le poids du corps suffisent.', 'Enchaîner 4 tours de : 10 pompes, 15 squats, 20 secondes de planche.', array['Repose-toi 1 minute entre les tours.', 'Garde la qualité du geste avant la vitesse.']::text[], '{"type":"counter","target":4,"unit":"tours"}'::jsonb, array['sans matériel', 'sport']::text[], true),
('for-medium-l-audace-du-voyageur', 'catalog', 'FOR', 'medium', array['weekly']::text[], 'L’Audace du Voyageur', 'Certains pays ne s’atteignent qu’en poussant une porte inconnue. Oser est la moitié du voyage.', 'Entrer seul dans un lieu où tu ne vas jamais (cours, café, salle, atelier) et y rester au moins 20 minutes.', array['Prépare une phrase d’entrée : « Bonjour, c’est ma première fois. »', 'Il n’y a rien à prouver.']::text[], '{"type":"simple"}'::jsonb, array['social', 'extérieur']::text[], true),
('for-medium-la-lame-affutee', 'catalog', 'FOR', 'medium', array['daily']::text[], 'La Lame Affûtée', 'Une lame s’émousse sans entretien. Quelques minutes bien employées valent mieux qu’un rattrapage héroïque.', 'Faire 15 minutes de renforcement ciblé sur un point faible : dos, épaules ou jambes.', array['Choisis deux exercices et fais-les bien.', 'Compte tes répétitions pour mesurer ta progression.']::text[], '{"type":"timer","minutes":15}'::jsonb, array['sans matériel', 'sport']::text[], true),
('for-medium-les-murailles-de-la-cite', 'catalog', 'FOR', 'medium', array['daily', 'weekly']::text[], 'Les Murailles de la Cité', 'La cité tient parce que chaque pierre porte son poids. Toi, tu portes les tiennes.', 'Faire 60 pompes, 80 squats et 3 minutes de gainage au total sur la journée.', array['Répartis par séries courtes tout au long de la journée.', 'Compte au fur et à mesure.']::text[], '{"type":"counter","target":3,"unit":"séries"}'::jsonb, array['sans matériel', 'sport']::text[], true),
('for-medium-la-parole-du-heraut', 'catalog', 'FOR', 'medium', array['weekly']::text[], 'La Parole du Héraut', 'Le héraut tremble avant de parler. Puis la place se tait, et c’est lui qui décide de la suite.', 'Prendre la parole en réunion, en cours ou en groupe pour donner ton avis ou poser une question.', array['Prépare une phrase d’ouverture.', 'Parle un peu plus lentement que ce qui te semble naturel.']::text[], '{"type":"simple"}'::jsonb, array['social', 'sans matériel']::text[], true),
('for-medium-le-port-du-bouclier', 'catalog', 'FOR', 'medium', array['daily', 'weekly']::text[], 'Le Port du Bouclier', 'Un bouclier lourd ne se porte pas d’un bras mou. Il se mérite, répétition après répétition.', 'Faire 20 minutes de travail avec charge (haltères, sac lesté, bidons d’eau) en gardant un geste propre.', array['Charge modérée, mouvement lent.', 'Termine par 2 minutes d’étirements.']::text[], '{"type":"timer","minutes":20}'::jsonb, array['sport']::text[], true),
('for-medium-la-peur-apprivoisee', 'catalog', 'FOR', 'medium', array['daily']::text[], 'La Peur Apprivoisée', 'Même le plus redouté des dragons a eu un premier jour. Le tien commence en regardant ta peur en face.', 'Faire une chose que tu repousses depuis longtemps et qui te fait un peu peur (appel, démarche, message).', array['Découpe-la en un premier geste de 5 minutes.', 'Fais-la avant midi pour ne pas la porter toute la journée.']::text[], '{"type":"simple"}'::jsonb, array['sans matériel']::text[], true),
('for-medium-le-chemin-des-cimes', 'catalog', 'FOR', 'medium', array['weekly']::text[], 'Le Chemin des Cimes', 'On n’atteint pas le col sans monter. Chaque pente est un passage de grade.', 'Faire une marche ou randonnée avec au moins 200 m de dénivelé positif.', array['Prends de l’eau et un coupe-vent.', 'Monte à ton rythme, sans te presser.']::text[], '{"type":"simple"}'::jsonb, array['extérieur', 'sport']::text[], true),
('for-medium-la-joute-du-matin', 'catalog', 'FOR', 'medium', array['daily', 'weekly']::text[], 'La Joute du Matin', 'À l’aube, la lice est vide. Ceux qui s’y entraînent déjà ont une avance que personne ne verra.', 'Faire 25 minutes de sport avant 9 h.', array['Prépare tes affaires la veille.', 'Commence doucement les 5 premières minutes.']::text[], '{"type":"timer","minutes":25}'::jsonb, array['sport']::text[], true),
('for-medium-le-nouveau-sentier', 'catalog', 'FOR', 'medium', array['weekly']::text[], 'Le Nouveau Sentier', 'Les cartes sont toujours incomplètes. C’est aux aventuriers de les remplir.', 'Essayer une activité que tu n’as jamais faite (escalade, danse, cuisine d’un pays, atelier) pendant au moins 30 minutes.', array['Choisis l’activité qui t’intrigue le plus.', 'Les débutants sont les bienvenus presque partout.']::text[], '{"type":"simple"}'::jsonb, array['extérieur']::text[], true),
('for-medium-le-pas-de-l-eclaireur', 'catalog', 'FOR', 'medium', array['daily', 'weekly']::text[], 'Le Pas de l’Éclaireur', 'L’éclaireur court devant l’armée, léger, pour voir ce que les autres ne voient pas encore.', 'Faire 5 séries de 30 secondes de montées de genoux ou de burpees, avec 30 secondes de repos.', array['Adapte l’intensité à ta forme du jour.', 'Bois quelques gorgées d’eau après.']::text[], '{"type":"counter","target":5,"unit":"séries"}'::jsonb, array['sans matériel', 'sport']::text[], true),
('for-high-le-siege-de-la-tour', 'catalog', 'FOR', 'high', array['weekly']::text[], 'Le Siège de la Tour', 'Une tour ne tombe pas en un assaut. Elle cède sous la répétition des coups.', 'Faire 4 séances de musculation ou de renforcement de 45 minutes dans la semaine.', array['Place-les un jour sur deux pour récupérer.', 'Note tes charges pour voir ta progression.']::text[], '{"type":"counter","target":4,"unit":"séances"}'::jsonb, array['sport']::text[], true),
('for-high-le-defi-de-la-barre', 'catalog', 'FOR', 'high', array['weekly', 'monthly']::text[], 'Le Défi de la Barre', 'Les forgerons comptent les coups de marteau. Toi, tu comptes tes tractions.', 'Battre ton record personnel sur un exercice de force (pompes, tractions, squats, gainage).', array['Mesure ton record de départ en début de période.', 'Prépare-le sur plusieurs séances.']::text[], '{"type":"simple"}'::jsonb, array['sport']::text[], true),
('for-high-la-longue-marche', 'catalog', 'FOR', 'high', array['daily', 'weekly']::text[], 'La Longue Marche', 'Les armées gagnent avec leurs jambes avant leurs lances. Marcher longtemps est un entraînement de roi.', 'Marcher 8 000 pas de plus que d’habitude dans la journée.', array['Fractionne : 20 minutes le matin, 30 le midi, 20 le soir.', 'Un podcast rend les pas plus légers.']::text[], '{"type":"counter","target":8000,"unit":"pas"}'::jsonb, array['extérieur']::text[], true),
('for-high-la-prise-de-parole-royale', 'catalog', 'FOR', 'high', array['weekly', 'monthly']::text[], 'La Prise de Parole Royale', 'Le roi écoute celui qui a préparé son discours. Le conseil retient celui qui l’a dit avec le cœur.', 'Présenter un sujet ou défendre une idée devant au moins 3 personnes.', array['Prépare trois points maximum.', 'Répète à voix haute une fois avant.']::text[], '{"type":"simple"}'::jsonb, array['social']::text[], true),
('for-high-les-trois-armes-de-la-garnison', 'catalog', 'FOR', 'high', array['weekly']::text[], 'Les Trois Armes de la Garnison', 'Une garnison solide s’entraîne à marcher, courir et porter. Elle n’en néglige aucune.', 'Faire 3 séances variées dans la semaine : une de force, une de cardio, une de mobilité.', array['Varie les plaisirs pour tenir dans la durée.', 'Chaque séance dure au moins 30 minutes.']::text[], '{"type":"counter","target":3,"unit":"séances"}'::jsonb, array['sport']::text[], true),
('for-high-l-ascension-du-bastion', 'catalog', 'FOR', 'high', array['monthly']::text[], 'L’Ascension du Bastion', 'Chaque bastion a commencé par un premier plan. Le tien commence par une série de séances régulières.', 'Faire au moins 12 séances de sport dans le mois.', array['Cale-les dans ton agenda dès le début du mois.', 'Une séance courte vaut mieux qu’une séance manquée.']::text[], '{"type":"counter","target":12,"unit":"séances"}'::jsonb, array['sport']::text[], true),
('for-high-le-dos-du-geant', 'catalog', 'FOR', 'high', array['weekly', 'monthly']::text[], 'Le Dos du Géant', 'Un géant se reconnaît à son dos, pas à ses bras. La force vient de ce qu’on ne voit pas.', 'Faire 3 séances centrées sur le dos et le gainage dans la semaine, d’au moins 30 minutes chacune.', array['Rameur, élastique, tractions assistées ou superman.', 'Reste lent et contrôlé.']::text[], '{"type":"counter","target":3,"unit":"séances"}'::jsonb, array['sport']::text[], true),
('for-high-la-journee-des-defis', 'catalog', 'FOR', 'high', array['weekly']::text[], 'La Journée des Défis', 'Chaque semaine, le village organise un concours. Toi, tu t’inscris à celui qui te fait hésiter.', 'Participer à un défi qui te sort de ta zone de confort : cours d’essai, inscription à une course, scène ouverte.', array['Inscris-toi d’abord, réfléchis après.', 'Raconte-le à un ami pour t’engager.']::text[], '{"type":"simple"}'::jsonb, array['social']::text[], true),
('for-high-l-epreuve-du-froid', 'catalog', 'FOR', 'high', array['weekly', 'monthly']::text[], 'L’Épreuve du Froid', 'Le nord ne pardonne pas aux imprudents. Mais ceux qui s’y préparent y trouvent un calme que le sud ignore.', 'Prendre 5 douches fraîches d’1 minute dans la période, après avis médical si besoin.', array['Commence tiède, termine frais, ne force pas.', 'Ne le fais pas si tu es malade ou en cas de problème cardiaque.']::text[], '{"type":"counter","target":5,"unit":"douches"}'::jsonb, array['sans matériel']::text[], true),
('for-expert-l-heritage-du-titan', 'catalog', 'FOR', 'expert', array['monthly']::text[], 'L’Héritage du Titan', 'Les anciens racontent qu’un titan portait une montagne sur ses épaules. Il avait commencé par un caillou.', 'Gagner 20 % sur un exercice de référence (tractions, développé couché, squats) en un mois, mesuré au début et à la fin. Adapte à ta condition, consulte un professionnel si besoin.', array['Note ta performance de départ dès le premier jour.', 'Augmente progressivement, jamais d’un coup.']::text[], '{"type":"steps","steps":["Mesurer ma référence au départ","Planifier 12 séances","Atteindre +20 %","Mesurer ma référence finale"]}'::jsonb, array['sport']::text[], true),
('for-expert-la-course-du-heros', 'catalog', 'FOR', 'expert', array['monthly', 'epic']::text[], 'La Course du Héros', 'On raconte qu’un messager a couru jusqu’à l’épuisement pour annoncer la victoire. Toi, tu courras pour arriver.', 'Participer à une course officielle de 10 km ou plus, ou parcourir cette distance en une fois. Adapte à ta condition, consulte un professionnel si besoin.', array['Suis un plan d’entraînement progressif sur au moins 6 semaines.', 'Dors bien la veille.']::text[], '{"type":"steps","steps":["Choisir la course ou le parcours","Suivre mon plan d’entraînement","Courir la distance"]}'::jsonb, array['sport', 'extérieur']::text[], true),
('for-expert-la-grande-prise-de-parole', 'catalog', 'FOR', 'expert', array['weekly', 'monthly']::text[], 'La Grande Prise de Parole', 'Le Conseil des Seigneurs n’écoute que ceux qui parlent debout. Le tien t’attend.', 'Prendre la parole devant au moins 10 personnes (présentation, discours, scène ouverte).', array['Prépare trois idées et une histoire.', 'Filme-toi une fois pour t’entendre.']::text[], '{"type":"steps","steps":["Préparer mon propos","Répéter à voix haute","Prendre la parole","Noter ce que je retiens"]}'::jsonb, array['social']::text[], true),
('for-expert-le-defi-des-trente-jours', 'catalog', 'FOR', 'expert', array['monthly', 'epic']::text[], 'Le Défi des Trente Jours', 'Il faut une lune entière pour changer un geste en habitude. Les anciens appelaient cela le grand cycle.', 'Faire au moins 25 séances de sport dans le mois, notées dans un carnet. Adapte à ta condition.', array['Prévois deux jours de repos par semaine.', 'Coche chaque séance sans te juger.']::text[], '{"type":"counter","target":25,"unit":"séances"}'::jsonb, array['sport']::text[], true),
('for-expert-la-montagne-gravie', 'catalog', 'FOR', 'expert', array['monthly']::text[], 'La Montagne Gravie', 'Les sommets ne se prennent pas, ils se méritent. Le seul adversaire de la montagne, c’est la préparation.', 'Réaliser une randonnée d’au moins 800 m de dénivelé positif, en préparant l’itinéraire et la météo. Adapte à ta condition.', array['Pars avec quelqu’un ou préviens un proche.', 'Emporte eau, vivres et vêtements chauds.']::text[], '{"type":"steps","steps":["Choisir l’itinéraire","Vérifier la météo","Faire la randonnée"]}'::jsonb, array['extérieur', 'sport']::text[], true),
('dex-easy-l-eveil-du-felin', 'catalog', 'DEX', 'easy', array['daily']::text[], 'L’Éveil du Félin', 'Le chat ne se lève jamais sans s’étirer. Il ne se blesse jamais non plus. Coïncidence ?', 'Faire 5 minutes d’étirements au réveil.', array['Tiens chaque position 20 à 30 secondes.', 'Ne cherche jamais la douleur, seulement la tension.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('dex-easy-la-plume-du-scribe', 'catalog', 'DEX', 'easy', array['daily']::text[], 'La Plume du Scribe', 'Un scribe ne dort pas avant d’avoir couché quelques lignes. Les idées ne vivent que sur le papier.', 'Écrire 10 lignes de ton choix : récit, poème, lettre, pensées.', array['Ne te relis pas avant d’avoir fini.', 'Un chrono de 5 minutes aide à démarrer.']::text[], '{"type":"counter","target":10,"unit":"lignes"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('dex-easy-le-croquis-du-voyageur', 'catalog', 'DEX', 'easy', array['daily']::text[], 'Le Croquis du Voyageur', 'Les cartographes dessinent ce qu’ils voient, pas ce qu’ils croient voir. L’œil s’éduque au crayon.', 'Dessiner un objet de ta pièce pendant 10 minutes.', array['Commence par les grandes formes, les détails viennent après.', 'Aucun jugement : un croquis est un exercice.']::text[], '{"type":"timer","minutes":10}'::jsonb, array['moins de 10 min']::text[], true),
('dex-easy-la-gamme-du-menestrel', 'catalog', 'DEX', 'easy', array['daily']::text[], 'La Gamme du Ménestrel', 'Le ménestrel qui saute ses gammes oublie bientôt sa chanson. Cinq minutes valent mieux qu’un grand soir.', 'Jouer 5 minutes d’un instrument, ou chanter 5 minutes.', array['Commence par ce que tu sais déjà jouer.', 'Une seule difficulté à travailler, pas dix.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['moins de 10 min']::text[], true),
('dex-easy-les-anneaux-du-jongleur', 'catalog', 'DEX', 'easy', array['daily']::text[], 'Les Anneaux du Jongleur', 'Trois balles ne s’apprivoisent pas d’un coup. Chaque chute apprend à la main où se trouve le ciel.', 'Pratiquer 5 minutes de jonglage, d’équilibre ou d’un tour d’adresse.', array['Deux balles d’abord, trois quand c’est fluide.', 'Ne regarde pas tes mains, regarde le sommet de la trajectoire.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('dex-easy-la-page-blanche-du-poete', 'catalog', 'DEX', 'easy', array['daily']::text[], 'La Page Blanche du Poète', 'Les poètes de la cour avaient un secret : ils écrivaient avant d’avoir une idée.', 'Écrire un haïku (3 vers de 5, 7 et 5 syllabes) ou un court poème.', array['Pars d’un détail de ta journée.', 'Compte les syllabes sur tes doigts.']::text[], '{"type":"simple"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('dex-easy-le-pli-de-l-origamiste', 'catalog', 'DEX', 'easy', array['daily']::text[], 'Le Pli de l’Origamiste', 'Une feuille, un pli, une grue. L’artisan sait que la patience est la première des matières.', 'Plier un origami ou fabriquer un petit objet de papier.', array['Suis un tutoriel simple si besoin.', 'Marque bien chaque pli avec l’ongle.']::text[], '{"type":"simple"}'::jsonb, array['moins de 10 min']::text[], true),
('dex-easy-le-carnet-de-l-inventeur', 'catalog', 'DEX', 'easy', array['daily']::text[], 'Le Carnet de l’Inventeur', 'Les grandes inventions commencent sur un coin de nappe. Garde de quoi noter.', 'Noter 3 idées (projets, cadeaux, histoires, améliorations) dans un carnet ou une note.', array['Aucune idée n’est trop folle à ce stade.', 'Écris-les en une phrase, pas plus.']::text[], '{"type":"counter","target":3,"unit":"idées"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('dex-easy-la-danse-des-epaules', 'catalog', 'DEX', 'easy', array['daily']::text[], 'La Danse des Épaules', 'Le dos du scribe se courbe vite. Un peu de mouvement rend à la plume sa légèreté.', 'Faire 5 minutes de mobilité du cou, des épaules et du dos.', array['Roule les épaules en grands cercles.', 'Ouvre la cage thoracique en inspirant.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('dex-easy-la-couleur-du-jour', 'catalog', 'DEX', 'easy', array['daily']::text[], 'La Couleur du Jour', 'Chaque journée a sa couleur. Les peintres de la cour en choisissaient une dès le matin.', 'Photographier ou dessiner quelque chose de la couleur de ton choix du jour.', array['Regarde autour de toi avant de choisir.', 'Prends de la distance pour cadrer.']::text[], '{"type":"simple"}'::jsonb, array['moins de 10 min']::text[], true),
('dex-easy-l-atelier-de-la-musique', 'catalog', 'DEX', 'easy', array['daily']::text[], 'L’Atelier de la Musique', 'Un air entendu dix fois finit par vivre dans les doigts. Écoute-le avec l’oreille d’un musicien.', 'Écouter attentivement un morceau en entier, sans écran, et noter ce qui t’a frappé.', array['Choisis un style que tu connais peu.', 'Repère un instrument et suis-le tout du long.']::text[], '{"type":"simple"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('dex-easy-le-n-ud-du-marin', 'catalog', 'DEX', 'easy', array['daily']::text[], 'Le Nœud du Marin', 'Un marin sans nœuds est un passager. Les mains savent des choses que l’esprit oublie.', 'Apprendre ou revoir un nœud, un pliage ou une technique manuelle simple.', array['Suis un tutoriel pas à pas.', 'Refais-le trois fois pour qu’il reste.']::text[], '{"type":"simple"}'::jsonb, array['moins de 10 min']::text[], true),
('dex-easy-la-pose-du-sage', 'catalog', 'DEX', 'easy', array['daily']::text[], 'La Pose du Sage', 'Dans l’ancienne école du monastère, la souplesse précédait la sagesse.', 'Tenir une posture de yoga ou d’étirement pendant 2 minutes au total.', array['Reste sur des postures simples.', 'Respire lentement, sans forcer.']::text[], '{"type":"timer","minutes":2}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('dex-easy-l-echo-du-dessinateur', 'catalog', 'DEX', 'easy', array['daily']::text[], 'L’Écho du Dessinateur', 'Recopier un maître est la plus vieille manière d’apprendre. Ton trait finira par trouver sa voix.', 'Copier un détail d’une œuvre qui te plaît (un visage, une main, un motif) en 10 minutes.', array['Observe d’abord, trace ensuite.', 'Concentre-toi sur les proportions.']::text[], '{"type":"timer","minutes":10}'::jsonb, array['moins de 10 min']::text[], true),
('dex-medium-les-doigts-du-menestrel', 'catalog', 'DEX', 'medium', array['daily', 'weekly']::text[], 'Les Doigts du Ménestrel', 'Le ménestrel joue sans regarder ses mains. Il y a longtemps, il les regardait beaucoup.', 'Pratiquer 20 minutes une activité manuelle : instrument, dessin, jonglage, maquette.', array['Fixe-toi un petit objectif pour la séance.', 'Enregistre-toi ou photographie ton avancée.']::text[], '{"type":"timer","minutes":20}'::jsonb, array['sans matériel']::text[], true),
('dex-medium-le-chapitre-du-romancier', 'catalog', 'DEX', 'medium', array['daily', 'weekly']::text[], 'Le Chapitre du Romancier', 'Les romans ne s’écrivent pas, ils s’empilent. Une page aujourd’hui, un royaume demain.', 'Écrire pendant 20 minutes sans t’arrêter, sur un projet ou un texte libre.', array['Désactive les notifications.', 'Écris d’abord, corrige un autre jour.']::text[], '{"type":"timer","minutes":20}'::jsonb, array['sans matériel']::text[], true),
('dex-medium-le-pinceau-de-l-enlumineur', 'catalog', 'DEX', 'medium', array['daily']::text[], 'Le Pinceau de l’Enlumineur', 'Les moines passaient des mois sur une lettrine. Toi, tu as quinze minutes pour y croire.', 'Dessiner ou peindre 15 minutes d’après nature : une plante, un visage, une rue.', array['Essaie un matériau différent de d’habitude.', 'Ne gomme pas : superpose les traits.']::text[], '{"type":"timer","minutes":15}'::jsonb, array['extérieur']::text[], true),
('dex-medium-la-recette-du-guerisseur', 'catalog', 'DEX', 'medium', array['weekly']::text[], 'La Recette du Guérisseur', 'L’apothicaire invente avant de goûter. La cuisine est la plus ancienne des alchimies.', 'Cuisiner un plat que tu n’as jamais préparé, en suivant ou en adaptant une recette.', array['Prépare tous les ingrédients avant de commencer.', 'Note ce que tu changerais.']::text[], '{"type":"simple"}'::jsonb, array['cuisine']::text[], true),
('dex-medium-le-pas-du-danseur', 'catalog', 'DEX', 'medium', array['daily', 'weekly']::text[], 'Le Pas du Danseur', 'La cour entière se tait quand le danseur entre. Un pas juste vaut mieux qu’un long discours.', 'Danser ou bouger sur de la musique pendant 15 minutes, seul ou à plusieurs.', array['Mets un morceau que tu aimes vraiment.', 'Laisse le corps décider, pas la tête.']::text[], '{"type":"timer","minutes":15}'::jsonb, array['sans matériel', 'sport']::text[], true),
('dex-medium-l-atelier-du-bricoleur', 'catalog', 'DEX', 'medium', array['weekly']::text[], 'L’Atelier du Bricoleur', 'Ce qui est cassé n’est pas perdu : c’est un chantier. L’artisan sait réparer ce que d’autres jetteraient.', 'Réparer, fabriquer ou customiser un objet que tu avais mis de côté.', array['Regarde un tutoriel avant de t’y mettre.', 'Prévois les outils à l’avance.']::text[], '{"type":"simple"}'::jsonb, array['bricolage']::text[], true),
('dex-medium-le-photographe-des-cimes', 'catalog', 'DEX', 'medium', array['daily', 'weekly']::text[], 'Le Photographe des Cimes', 'Un instantané bien cadré raconte plus qu’un long discours. Cherche la lumière.', 'Prendre 20 photos soignées en te promenant, puis en garder 3 que tu trouves réussies.', array['Change d’angle : plus bas, plus haut, de côté.', 'Regarde la lumière avant le sujet.']::text[], '{"type":"counter","target":3,"unit":"photos"}'::jsonb, array['extérieur']::text[], true),
('dex-medium-la-gamme-du-virtuose', 'catalog', 'DEX', 'medium', array['daily']::text[], 'La Gamme du Virtuose', 'La vélocité vient de la lenteur. Le virtuose répète avec patience ce que le public applaudit à toute allure.', 'Travailler 20 minutes un passage difficile d’un morceau, lentement.', array['Isole 4 mesures, pas plus.', 'Augmente le tempo seulement quand c’est propre.']::text[], '{"type":"timer","minutes":20}'::jsonb, array['moins de 20 min']::text[], true),
('dex-medium-l-histoire-du-conteur', 'catalog', 'DEX', 'medium', array['weekly']::text[], 'L’Histoire du Conteur', 'Autour du feu, tout le monde écoute celui qui sait raconter. Tes histoires méritent d’être dites.', 'Écrire ou raconter une histoire courte (une page, ou 3 minutes enregistrées).', array['Un personnage, un obstacle, une fin.', 'Lis-la à voix haute pour la corriger.']::text[], '{"type":"simple"}'::jsonb, array['sans matériel']::text[], true),
('dex-medium-le-souffle-du-yogi', 'catalog', 'DEX', 'medium', array['daily', 'weekly']::text[], 'Le Souffle du Yogi', 'Le corps qui plie ne rompt pas. Les anciens enseignaient la souplesse avant la force.', 'Faire une séance de yoga ou de mobilité de 20 minutes.', array['Suis une vidéo guidée si tu débutes.', 'Reste à l’écoute des limites de ton corps.']::text[], '{"type":"timer","minutes":20}'::jsonb, array['sans matériel', 'sport']::text[], true),
('dex-medium-la-page-du-carnet-intime', 'catalog', 'DEX', 'medium', array['weekly']::text[], 'La Page du Carnet Intime', 'Un journal dessiné garde ce que les mots ne retiennent pas.', 'Réaliser une double page de carnet (dessin, collage, écriture) sur ta semaine.', array['Mélange texte et images.', 'Pas besoin que ce soit beau, seulement vrai.']::text[], '{"type":"simple"}'::jsonb, array['sans matériel']::text[], true),
('dex-medium-le-jeu-de-mains-du-magicien', 'catalog', 'DEX', 'medium', array['daily', 'weekly']::text[], 'Le Jeu de Mains du Magicien', 'Le tour de passe-passe n’est pas de la magie : c’est dix mille répétitions invisibles.', 'Apprendre un tour de magie, de cartes ou de jonglage et le présenter à quelqu’un.', array['Choisis un tour court et propre.', 'Répète devant un miroir.']::text[], '{"type":"simple"}'::jsonb, array['social']::text[], true),
('dex-high-la-danse-des-lames', 'catalog', 'DEX', 'high', array['weekly']::text[], 'La Danse des Lames', 'Le duel est une danse. Celui qui maîtrise son corps choisit la cadence.', 'Faire une séance d’1 heure de yoga, danse, escalade ou art martial.', array['Réserve le créneau dans ton agenda.', 'Choisis une activité que tu aimes vraiment.']::text[], '{"type":"timer","minutes":60}'::jsonb, array['sport']::text[], true),
('dex-high-le-manuscrit-en-cours', 'catalog', 'DEX', 'high', array['weekly', 'monthly']::text[], 'Le Manuscrit en Cours', 'Les grands livres n’ont jamais été écrits en un jour. Mais ils ont tous eu un premier chapitre.', 'Écrire 3 sessions de 30 minutes dans la semaine sur un projet d’écriture.', array['Garde le même créneau chaque jour.', 'Note le nombre de mots pour te voir avancer.']::text[], '{"type":"counter","target":3,"unit":"sessions"}'::jsonb, array['sans matériel']::text[], true),
('dex-high-l-atelier-de-l-artisan', 'catalog', 'DEX', 'high', array['weekly']::text[], 'L’Atelier de l’Artisan', 'Il y a des gestes que seule la main sait. Il faut lui laisser le temps de les apprendre.', 'Consacrer 3 sessions d’au moins 30 minutes à un projet manuel (menuiserie, couture, modélisme, poterie…).', array['Prépare ton espace de travail une fois pour toutes.', 'Photographie l’avancement.']::text[], '{"type":"counter","target":3,"unit":"sessions"}'::jsonb, array['bricolage']::text[], true),
('dex-high-le-concert-interieur', 'catalog', 'DEX', 'high', array['daily', 'weekly']::text[], 'Le Concert Intérieur', 'Un récital commence dans la tête du musicien. Tout le reste n’est que la mise en son.', 'Jouer ou chanter un morceau en entier, de bout en bout, et l’enregistrer.', array['Écoute l’enregistrement et note un point à améliorer.', 'Ne t’arrête pas aux erreurs : finis le morceau.']::text[], '{"type":"simple"}'::jsonb, array['sans matériel']::text[], true),
('dex-high-la-cuisine-du-banquet', 'catalog', 'DEX', 'high', array['weekly', 'monthly']::text[], 'La Cuisine du Banquet', 'Les banquets du roi rassemblaient les villages. Ton menu rassemble ceux que tu invites.', 'Cuisiner un repas complet (entrée, plat, dessert) pour au moins 2 personnes.', array['Planifie les courses la veille.', 'Prépare ce qui peut l’être en avance.']::text[], '{"type":"simple"}'::jsonb, array['cuisine', 'social']::text[], true),
('dex-high-le-carnet-de-croquis', 'catalog', 'DEX', 'high', array['monthly']::text[], 'Le Carnet de Croquis', 'Chaque jour un trait, et en un mois tu auras un livre.', 'Dessiner au moins 15 jours dans le mois, même 10 minutes, dans un même carnet.', array['Garde le carnet à portée de main.', 'Date chaque page.']::text[], '{"type":"counter","target":15,"unit":"jours"}'::jsonb, array['sans matériel']::text[], true),
('dex-high-la-scene-ouverte', 'catalog', 'DEX', 'high', array['weekly']::text[], 'La Scène Ouverte', 'Toute cour a son estrade. Il faut parfois monter sans avoir fini de répéter.', 'Montrer une création à au moins 3 personnes (texte, dessin, morceau, vidéo) et recueillir leur avis.', array['Choisis des personnes bienveillantes mais honnêtes.', 'Écoute avant de te défendre.']::text[], '{"type":"simple"}'::jsonb, array['social']::text[], true),
('dex-high-le-mur-d-escalade', 'catalog', 'DEX', 'high', array['weekly', 'monthly']::text[], 'Le Mur d’Escalade', 'Chaque prise est un problème, chaque problème une danse. Grimper, c’est penser avec les mains.', 'Faire 2 séances d’escalade, de bloc, de danse ou de gymnastique dans la semaine.', array['Échauffe-toi bien avant.', 'Va à ton rythme, sans te comparer.']::text[], '{"type":"counter","target":2,"unit":"séances"}'::jsonb, array['sport']::text[], true),
('dex-high-le-mois-du-grand-projet', 'catalog', 'DEX', 'high', array['monthly']::text[], 'Le Mois du Grand Projet', 'Un projet créatif n’avance que si on le visite chaque semaine. Le tien t’attend.', 'Consacrer au moins 10 heures à un projet créatif dans le mois (suivies dans un carnet).', array['Planifie 2 à 3 heures par semaine.', 'Note la durée de chaque session.']::text[], '{"type":"counter","target":10,"unit":"heures"}'::jsonb, array['sans matériel']::text[], true),
('dex-expert-le-chef-d-uvre-de-l-artisan', 'catalog', 'DEX', 'expert', array['monthly']::text[], 'Le Chef-d’œuvre de l’Artisan', 'Dans la guilde, on ne devient maître qu’en présentant un chef-d’œuvre. Le tien t’attend.', 'Terminer un projet manuel complet en un mois : un morceau joué en entier, un meuble, un carnet de croquis de 30 pages.', array['Définis le résultat attendu dès le premier jour.', 'Fractionne en étapes de 2 à 3 heures.']::text[], '{"type":"steps","steps":["Définir le projet","Rassembler le matériel","Réaliser les trois quarts","Terminer et présenter"]}'::jsonb, array['bricolage']::text[], true),
('dex-expert-le-grand-recit', 'catalog', 'DEX', 'expert', array['monthly', 'epic']::text[], 'Le Grand Récit', 'Les épopées sont la mémoire des peuples. Écris la tienne, ligne après ligne.', 'Écrire une nouvelle ou un récit de 5 000 mots, de la première à la dernière ligne.', array['Écris 300 mots par jour.', 'Termine avant de corriger.']::text[], '{"type":"steps","steps":["Écrire le plan","Écrire la première moitié","Écrire la seconde moitié","Relire et corriger"]}'::jsonb, array['sans matériel']::text[], true),
('dex-expert-le-recital-du-barde', 'catalog', 'DEX', 'expert', array['weekly', 'monthly']::text[], 'Le Récital du Barde', 'Un barde n’est un barde que le jour où il joue devant les autres.', 'Jouer, chanter ou présenter une création devant au moins 5 personnes.', array['Prépare un morceau court mais maîtrisé.', 'Demande un retour sincère après.']::text[], '{"type":"steps","steps":["Choisir et préparer le morceau","Répéter 5 fois","Se produire en public"]}'::jsonb, array['social']::text[], true),
('dex-expert-l-exposition-de-la-guilde', 'catalog', 'DEX', 'expert', array['monthly', 'epic']::text[], 'L’Exposition de la Guilde', 'Les œuvres qui restent dans un tiroir ne changent jamais le monde. Sors les tiennes.', 'Rassembler 10 créations et les exposer ou les publier (en ligne, entre amis, en galerie).', array['Choisis un fil conducteur.', 'Demande de l’aide pour la mise en forme.']::text[], '{"type":"steps","steps":["Rassembler mes créations","Les mettre en forme","Les montrer au public"]}'::jsonb, array['social']::text[], true),
('dex-expert-la-trentaine-du-pinceau', 'catalog', 'DEX', 'expert', array['monthly']::text[], 'La Trentaine du Pinceau', 'Trente jours, trente œuvres : le meilleur entraînement est celui qu’on ne saute pas.', 'Créer quelque chose chaque jour pendant 30 jours (dessin, texte, musique, photo) et le noter.', array['Fixe-toi un minimum de 10 minutes.', 'Garde tout au même endroit.']::text[], '{"type":"counter","target":30,"unit":"jours"}'::jsonb, array['sans matériel']::text[], true),
('con-easy-l-epreuve-de-l-eau-claire', 'catalog', 'CON', 'easy', array['daily']::text[], 'L’Épreuve de l’Eau Claire', 'Les nomades du désert ne gaspillent jamais une goutte. Ils n’oublient jamais de boire non plus.', 'Boire 1,5 L d’eau dans la journée.', array['Garde une gourde à portée de main.', 'Un verre au réveil, un avant chaque repas.']::text[], '{"type":"counter","target":6,"unit":"verres"}'::jsonb, array['sans matériel']::text[], true),
('con-easy-la-marche-du-pelerin', 'catalog', 'CON', 'easy', array['daily']::text[], 'La Marche du Pèlerin', 'Le pèlerin ne court pas. Il marche, chaque jour, et finit toujours par arriver.', 'Marcher 20 minutes d’affilée, dehors si possible.', array['Un peu d’air, sans écran.', 'Tu peux les répartir en plusieurs sorties.']::text[], '{"type":"timer","minutes":20}'::jsonb, array['extérieur', 'sans matériel']::text[], true),
('con-easy-le-festin-de-couleurs', 'catalog', 'CON', 'easy', array['daily']::text[], 'Le Festin de Couleurs', 'Une table de roi est bariolée. Les cuisiniers savent que les couleurs sont des promesses de vitalité.', 'Manger 5 fruits et légumes différents dans la journée.', array['Un fruit au petit-déjeuner, un légume à chaque repas.', 'Surgelés et conserves comptent.']::text[], '{"type":"counter","target":5,"unit":"portions"}'::jsonb, array['alimentation']::text[], true),
('con-easy-le-coucher-du-veilleur', 'catalog', 'CON', 'easy', array['daily']::text[], 'Le Coucher du Veilleur', 'La sentinelle épuisée ne voit pas venir l’ennemi. Le repos aussi est un devoir.', 'Éteindre les écrans 30 minutes avant de dormir.', array['Prépare une lecture ou une musique douce.', 'Mets le téléphone à charger hors du lit.']::text[], '{"type":"simple"}'::jsonb, array['sommeil', 'sans matériel']::text[], true),
('con-easy-le-souffle-du-matin', 'catalog', 'CON', 'easy', array['daily']::text[], 'Le Souffle du Matin', 'L’air frais du matin réveille les cités endormies. Ouvre ta fenêtre, ouvre tes poumons.', 'Aérer ta chambre et prendre 5 respirations profondes à la fenêtre au réveil.', array['Inspire par le nez, expire lentement par la bouche.', 'Profite de la lumière du jour.']::text[], '{"type":"simple"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('con-easy-la-pause-du-voyageur', 'catalog', 'CON', 'easy', array['daily']::text[], 'La Pause du Voyageur', 'Même la plus longue route comprend des haltes. Le voyageur avisé s’y étire.', 'Te lever et bouger 5 minutes toutes les heures assises, au moins 3 fois dans la journée.', array['Mets une alarme discrète.', 'Marche jusqu’à la fenêtre, étire-toi.']::text[], '{"type":"counter","target":3,"unit":"pauses"}'::jsonb, array['sans matériel']::text[], true),
('con-easy-le-soleil-du-matin', 'catalog', 'CON', 'easy', array['daily']::text[], 'Le Soleil du Matin', 'Les fermiers savent que le soleil du matin fait pousser plus que celui de midi.', 'Passer 10 minutes dehors à la lumière du jour avant midi.', array['Un café en terrasse ou un tour du pâté de maisons suffit.', 'Même sous les nuages, la lumière dehors compte.']::text[], '{"type":"timer","minutes":10}'::jsonb, array['extérieur', 'matin']::text[], true),
('con-easy-le-petit-dejeuner-du-forgeron', 'catalog', 'CON', 'easy', array['daily']::text[], 'Le Petit-déjeuner du Forgeron', 'Aucun forgeron n’allume la forge le ventre vide. Le feu a besoin de bois.', 'Prendre un vrai petit-déjeuner avec une source de protéines et un fruit.', array['Œufs, yaourt, fromage blanc, pain complet…', 'Prépare-le la veille pour les matins pressés.']::text[], '{"type":"simple"}'::jsonb, array['alimentation']::text[], true),
('con-easy-la-veillee-sans-sucre', 'catalog', 'CON', 'easy', array['daily']::text[], 'La Veillée sans Sucre', 'Les confiseurs du roi connaissaient le prix du miel. Ils n’en abusaient jamais avant la nuit.', 'Éviter les boissons sucrées et les sucreries pendant toute la journée.', array['Remplace par de l’eau, du thé ou du fruit.', 'Un dessert peut rester un plaisir : choisis-le consciemment.']::text[], '{"type":"simple"}'::jsonb, array['alimentation']::text[], true),
('con-easy-la-sieste-de-l-eclaireur', 'catalog', 'CON', 'easy', array['daily']::text[], 'La Sieste de l’Éclaireur', 'L’éclaireur averti dort quand il le peut. Dix minutes de repos valent une demi-nuit pour celui qui sait s’arrêter.', 'Faire une pause de 10 minutes les yeux fermés dans l’après-midi.', array['Mets un minuteur doux.', 'Allonge-toi ou assieds-toi confortablement.']::text[], '{"type":"timer","minutes":10}'::jsonb, array['sans matériel', 'sommeil']::text[], true),
('con-easy-l-escalier-du-guetteur', 'catalog', 'CON', 'easy', array['daily']::text[], 'L’Escalier du Guetteur', 'Le guetteur monte et descend sa tour dix fois par jour. Il ne s’est jamais plaint de ses jambes.', 'Prendre les escaliers à chaque occasion de la journée.', array['Compte les étages gagnés.', 'Descends aussi à pied.']::text[], '{"type":"simple"}'::jsonb, array['sans matériel']::text[], true),
('con-easy-la-posture-du-sage', 'catalog', 'CON', 'easy', array['daily']::text[], 'La Posture du Sage', 'On reconnaît un roi à sa posture avant ses paroles. Le dos droit est un royaume.', 'Faire 5 minutes d’exercices de posture (étirements, redressement, mobilité de la nuque).', array['Place le dos contre un mur, talons, fessiers et omoplates en contact.', 'Respire profondément.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('con-easy-la-soupe-du-soir', 'catalog', 'CON', 'easy', array['daily']::text[], 'La Soupe du Soir', 'Quand l’hiver tombe, la soupe est un sort de protection. Elle se prépare sans magie.', 'Cuisiner un plat maison avec des légumes plutôt que de commander ou réchauffer.', array['Une soupe ou une poêlée suffit.', 'Prévois-en pour le lendemain.']::text[], '{"type":"simple"}'::jsonb, array['cuisine', 'alimentation']::text[], true),
('con-easy-le-pas-compte', 'catalog', 'CON', 'easy', array['daily']::text[], 'Le Pas Compté', 'Les voyageurs comptent leurs lieues. Chaque pas est une pierre posée sur la route.', 'Atteindre 6 000 pas dans la journée.', array['Gare-toi plus loin, descends un arrêt avant.', 'Marche en téléphonant.']::text[], '{"type":"counter","target":6000,"unit":"pas"}'::jsonb, array['extérieur']::text[], true),
('con-medium-la-marche-du-pelerin-aguerri', 'catalog', 'CON', 'medium', array['daily', 'weekly']::text[], 'La Marche du Pèlerin Aguerri', 'Le pèlerin ne se presse pas, mais il ne s’arrête jamais. Aujourd’hui, il passe à la vitesse supérieure.', 'Marcher 30 minutes d’affilée à bon rythme.', array['Choisis un parcours que tu aimes.', 'Un rythme où tu peux parler mais pas chanter.']::text[], '{"type":"timer","minutes":30}'::jsonb, array['extérieur', 'sport']::text[], true),
('con-medium-le-galop-du-messager', 'catalog', 'CON', 'medium', array['daily', 'weekly']::text[], 'Le Galop du Messager', 'Les messagers du roi parcouraient des lieues au trot. Ton souffle, lui, se bâtit à petites foulées.', 'Courir ou trottiner 20 minutes, à une allure où tu peux encore parler.', array['Alterne course et marche si besoin.', 'Hydrate-toi avant et après.']::text[], '{"type":"timer","minutes":20}'::jsonb, array['extérieur', 'sport']::text[], true),
('con-medium-la-garde-de-nuit', 'catalog', 'CON', 'medium', array['weekly']::text[], 'La Garde de Nuit', 'Une sentinelle épuisée ne voit pas venir l’ennemi. Le repos aussi est un devoir.', 'Te coucher à heure fixe (± 30 min) 5 soirs sur 7.', array['Fixe une alarme de coucher.', 'Garde le même horaire le week-end.']::text[], '{"type":"counter","target":5,"unit":"soirs"}'::jsonb, array['sommeil']::text[], true),
('con-medium-la-journee-des-cinq-couleurs', 'catalog', 'CON', 'medium', array['daily']::text[], 'La Journée des Cinq Couleurs', 'La table du roi se reconnaissait à sa palette : rouge, vert, jaune, blanc, violet.', 'Manger au moins 5 couleurs de fruits et légumes dans la journée.', array['Prépare une salade multicolore.', 'Pense aux fruits secs et surgelés.']::text[], '{"type":"counter","target":5,"unit":"couleurs"}'::jsonb, array['alimentation']::text[], true),
('con-medium-le-velo-du-courrier', 'catalog', 'CON', 'medium', array['daily', 'weekly']::text[], 'Le Vélo du Courrier', 'La route est longue, mais elle se parcourt plus vite sur deux roues. Le vent est ton allié.', 'Faire 30 minutes de vélo (réel ou d’appartement) à un rythme soutenu.', array['Règle bien la selle.', 'Alterne montées et plat si tu peux.']::text[], '{"type":"timer","minutes":30}'::jsonb, array['extérieur', 'sport']::text[], true),
('con-medium-la-semaine-du-jardinier', 'catalog', 'CON', 'medium', array['weekly']::text[], 'La Semaine du Jardinier', 'Le jardinier sait que les récoltes viennent de gestes répétés. Ta santé aussi.', 'Cuisiner maison au moins 5 repas dans la semaine.', array['Prépare un menu le dimanche.', 'Cuisine en double pour le lendemain.']::text[], '{"type":"counter","target":5,"unit":"repas"}'::jsonb, array['cuisine', 'alimentation']::text[], true),
('con-medium-le-bain-de-nage', 'catalog', 'CON', 'medium', array['daily', 'weekly']::text[], 'Le Bain de Nage', 'L’eau dissout la fatigue comme elle emporte le fer des armures rouillées.', 'Nager ou faire 30 minutes d’une activité de cardio doux (vélo, rameur, marche rapide).', array['Varie les nages ou les allures.', 'Écoute ton souffle.']::text[], '{"type":"timer","minutes":30}'::jsonb, array['sport']::text[], true),
('con-medium-le-camp-sans-ecran', 'catalog', 'CON', 'medium', array['weekly']::text[], 'Le Camp sans Écran', 'Les voyageurs de jadis dormaient au rythme du feu. Retrouve le tien.', 'Éteindre tous les écrans une heure avant de dormir, 5 soirs sur 7.', array['Remplace par la lecture ou la discussion.', 'Mets le téléphone dans une autre pièce.']::text[], '{"type":"counter","target":5,"unit":"soirs"}'::jsonb, array['sommeil']::text[], true),
('con-medium-la-gourde-pleine', 'catalog', 'CON', 'medium', array['daily']::text[], 'La Gourde Pleine', 'Un guerrier déshydraté ne tient pas jusqu’au soir. Celui qui boit régulièrement gagne la journée.', 'Boire 2 L d’eau dans la journée.', array['Une gourde de 500 ml remplie 4 fois.', 'Ajoute du citron ou de la menthe si l’eau t’ennuie.']::text[], '{"type":"counter","target":2000,"unit":"ml"}'::jsonb, array['sans matériel']::text[], true),
('con-medium-l-entrainement-du-fantassin', 'catalog', 'CON', 'medium', array['weekly']::text[], 'L’Entraînement du Fantassin', 'Une armée se prépare dès le premier jour du printemps, pas la veille de la bataille.', 'Faire 3 séances de cardio de 30 minutes (course, vélo, natation, marche rapide) dans la semaine.', array['Place-les un jour sur deux.', 'Note ta durée pour voir ta progression.']::text[], '{"type":"counter","target":3,"unit":"séances"}'::jsonb, array['sport']::text[], true),
('con-medium-la-journee-sans-exces', 'catalog', 'CON', 'medium', array['daily', 'weekly']::text[], 'La Journée sans Excès', 'Le banquet est une joie, la modération est une force. Sache reconnaître ce qui te suffit.', 'Manger lentement et t’arrêter quand tu n’as plus faim à chaque repas de la journée.', array['Pose tes couverts entre les bouchées.', 'Mange sans écran.']::text[], '{"type":"counter","target":3,"unit":"repas"}'::jsonb, array['alimentation']::text[], true),
('con-medium-la-mobilite-du-funambule', 'catalog', 'CON', 'medium', array['weekly']::text[], 'La Mobilité du Funambule', 'Pour marcher sur un fil, le corps doit tout savoir de lui-même. Le tien commence par ses articulations.', 'Faire 3 séances de 15 minutes de mobilité ou d’étirements dans la semaine.', array['Concentre-toi sur hanches, dos et épaules.', 'Reste dans l’inconfort, pas dans la douleur.']::text[], '{"type":"counter","target":3,"unit":"séances"}'::jsonb, array['sans matériel']::text[], true),
('con-high-la-course-du-cinq-lieues', 'catalog', 'CON', 'high', array['weekly', 'monthly']::text[], 'La Course du Cinq Lieues', 'Le messager qui court cinq lieues n’est pas plus fort. Il est plus patient.', 'Courir 5 km (en une ou plusieurs fois selon ta forme).', array['Alterne course et marche au début.', 'Prépare-toi sur plusieurs semaines.']::text[], '{"type":"counter","target":5,"unit":"km"}'::jsonb, array['sport', 'extérieur']::text[], true),
('con-high-la-veillee-reguliere', 'catalog', 'CON', 'high', array['weekly']::text[], 'La Veillée Régulière', 'Les veilleurs ne dorment pas trop, ni trop peu. Ils dorment juste.', 'Dormir entre 7 et 9 heures chaque nuit pendant 6 nuits sur 7.', array['Prépare ta chambre : fraîche, sombre, silencieuse.', 'Garde le même réveil le week-end.']::text[], '{"type":"counter","target":6,"unit":"nuits"}'::jsonb, array['sommeil']::text[], true),
('con-high-le-mois-du-pelerin', 'catalog', 'CON', 'high', array['weekly', 'monthly']::text[], 'Le Mois du Pèlerin', 'Un pèlerinage ne se fait pas d’un coup. Chaque journée de marche en est un morceau.', 'Marcher 30 minutes par jour pendant 20 jours.', array['Intègre la marche à un trajet quotidien.', 'Coche chaque jour.']::text[], '{"type":"counter","target":20,"unit":"jours"}'::jsonb, array['extérieur']::text[], true),
('con-high-les-sept-jours-de-la-table', 'catalog', 'CON', 'high', array['weekly']::text[], 'Les Sept Jours de la Table', 'La table du roi change chaque jour. Ton assiette peut en faire autant.', 'Cuisiner un repas équilibré maison chaque jour pendant 7 jours.', array['Prépare les bases le dimanche.', 'Une protéine, un légume, un féculent.']::text[], '{"type":"counter","target":7,"unit":"jours"}'::jsonb, array['cuisine', 'alimentation']::text[], true),
('con-high-la-longue-etape', 'catalog', 'CON', 'high', array['daily', 'weekly']::text[], 'La Longue Étape', 'Les chroniques de voyage racontent toujours la dernière étape, jamais le chemin banal qui y mène.', 'Faire une sortie de 90 minutes à pied, à vélo ou à la nage à un rythme régulier.', array['Emporte eau et collation.', 'Pars à une heure fraîche.']::text[], '{"type":"timer","minutes":90}'::jsonb, array['extérieur', 'sport']::text[], true),
('con-high-les-vingt-veillees', 'catalog', 'CON', 'high', array['monthly']::text[], 'Les Vingt Veillées', 'Un mois de nuits régulières reconstruit un corps. Le chevalier ne s’en rend compte que plus tard.', 'Te coucher à heure fixe (± 30 min) au moins 20 nuits dans le mois.', array['Suis ton coucher dans un calendrier.', 'Décale doucement si besoin.']::text[], '{"type":"counter","target":20,"unit":"nuits"}'::jsonb, array['sommeil']::text[], true),
('con-high-le-souffle-de-l-archer', 'catalog', 'CON', 'high', array['weekly', 'monthly']::text[], 'Le Souffle de l’Archer', 'L’archer maîtrise sa respiration avant de bander son arc. Le cardio est sa première arme.', 'Faire 3 séances de cardio d’au moins 40 minutes dans la semaine.', array['Garde une allure où tu peux parler.', 'Alterne les disciplines.']::text[], '{"type":"counter","target":3,"unit":"séances"}'::jsonb, array['sport']::text[], true),
('con-high-la-cure-de-fraicheur', 'catalog', 'CON', 'high', array['weekly']::text[], 'La Cure de Fraîcheur', 'Les aubergistes du Nord vendent leurs fruits en saison : l’assiette de saison est la plus vivante.', 'Manger des fruits et légumes de saison à chaque repas pendant 5 jours.', array['Vise la moitié de l’assiette.', 'Marché ou cueillette de proximité si tu peux.']::text[], '{"type":"counter","target":5,"unit":"jours"}'::jsonb, array['alimentation']::text[], true),
('con-high-le-mois-des-mille-pas', 'catalog', 'CON', 'high', array['monthly']::text[], 'Le Mois des Mille Pas', 'Dix mille pas ne font pas un roi, mais ils font un marcheur. Et un marcheur arrive toujours.', 'Atteindre 8 000 pas au moins 20 jours dans le mois.', array['Mets ton compteur de pas à portée.', 'Marche en téléphonant.']::text[], '{"type":"counter","target":20,"unit":"jours"}'::jsonb, array['extérieur']::text[], true),
('con-expert-la-traversee-des-terres-brulees', 'catalog', 'CON', 'expert', array['monthly', 'epic']::text[], 'La Traversée des Terres Brûlées', 'Personne ne traverse les Terres Brûlées par hasard. On s’y prépare pendant des lunes.', 'Courir 10 km (ou un objectif d’endurance équivalent) en fin de période, après un plan d’entraînement suivi. Adapte à ta condition, consulte un professionnel si besoin.', array['Suis un plan progressif de 6 à 8 semaines.', 'Dors bien et mange suffisamment.']::text[], '{"type":"steps","steps":["Choisir mon plan d’entraînement","Suivre 3 sorties par semaine","Courir la distance cible"]}'::jsonb, array['sport', 'extérieur']::text[], true),
('con-expert-les-trente-soirs-du-veilleur', 'catalog', 'CON', 'expert', array['monthly']::text[], 'Les Trente Soirs du Veilleur', 'Une lune entière de nuits régulières change le corps et l’esprit.', 'Te coucher et te lever à heure régulière (± 30 min) pendant 30 jours.', array['Choisis un horaire réaliste.', 'Garde-le même le week-end.']::text[], '{"type":"counter","target":30,"unit":"jours"}'::jsonb, array['sommeil']::text[], true),
('con-expert-la-semaine-du-guerrier', 'catalog', 'CON', 'expert', array['weekly', 'monthly']::text[], 'La Semaine du Guerrier', 'Sept jours de rigueur douce : manger, dormir, bouger, sans excès ni privation.', 'Pendant 7 jours : dormir 7 à 9 h, bouger 30 minutes, boire 1,5 L d’eau et manger 5 fruits ou légumes chaque jour. Adapte à ta condition, consulte un professionnel si besoin.', array['Prépare tes repas à l’avance.', 'Coche chaque jour dans un carnet.']::text[], '{"type":"counter","target":7,"unit":"jours"}'::jsonb, array['sport', 'alimentation']::text[], true),
('con-expert-le-demi-tour-du-monde', 'catalog', 'CON', 'expert', array['monthly', 'epic']::text[], 'Le Demi-tour du Monde', 'Les récits parlent d’un coureur qui fit le tour du royaume en une saison. Toi, tu vises une grande distance.', 'Accomplir un objectif d’endurance de 21 km (course, marche rapide ou vélo 50 km). Adapte à ta condition, consulte un professionnel si besoin.', array['Prépare-toi sur au moins 10 semaines.', 'Teste ton équipement avant le jour J.']::text[], '{"type":"steps","steps":["Choisir l’épreuve","Suivre un plan sur 10 semaines","Réaliser l’épreuve"]}'::jsonb, array['sport', 'extérieur']::text[], true),
('con-expert-la-lune-sans-sucre', 'catalog', 'CON', 'expert', array['monthly']::text[], 'La Lune Sans Sucre', 'Les confiseurs en ont fait le serment : un mois sans miel pour redécouvrir le goût du pain.', 'Tenir 30 jours sans sucre ajouté (hors fruits). Adapte à ta condition, consulte un professionnel si besoin.', array['Lis les étiquettes : le sucre se cache partout.', 'Prévois des alternatives pour les envies.']::text[], '{"type":"counter","target":30,"unit":"jours"}'::jsonb, array['alimentation']::text[], true),
('int-easy-la-page-du-scribe', 'catalog', 'INT', 'easy', array['daily']::text[], 'La Page du Scribe', 'Un scribe ne recopie jamais un livre entier en une nuit. Une page par jour, et la bibliothèque se remplit.', 'Lire 10 pages d’un livre (pas un écran).', array['Garde le livre là où tu t’assieds le plus souvent.', 'Dix pages, c’est environ quinze minutes.']::text[], '{"type":"counter","target":10,"unit":"pages"}'::jsonb, array['sans matériel', 'moins de 20 min']::text[], true),
('int-easy-la-rune-du-jour', 'catalog', 'INT', 'easy', array['daily']::text[], 'La Rune du Jour', 'Les mages anciens apprenaient une rune par jour. Au bout d’un an, ils parlaient aux dragons.', 'Apprendre 5 mots d’une langue étrangère et les utiliser dans une phrase.', array['Dis-les à voix haute.', 'Associe chaque mot à une image.']::text[], '{"type":"counter","target":5,"unit":"mots"}'::jsonb, array['langue', 'moins de 10 min']::text[], true),
('int-easy-la-question-du-curieux', 'catalog', 'INT', 'easy', array['daily']::text[], 'La Question du Curieux', 'Le sage n’est pas celui qui répond, mais celui qui questionne sans honte.', 'Chercher la réponse à une question que tu t’es posée aujourd’hui, et la noter en une phrase.', array['Cherche dans une source fiable.', 'Écris ce que tu en retiens.']::text[], '{"type":"simple"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('int-easy-l-eclair-du-stratege', 'catalog', 'INT', 'easy', array['daily']::text[], 'L’Éclair du Stratège', 'Le stratège réfléchit en un coup d’œil. Mais il s’est longtemps entraîné à regarder.', 'Résoudre un problème de logique, une énigme ou un sudoku.', array['Pas de triche : prends ton temps.', 'Si tu bloques, change d’approche avant de regarder la solution.']::text[], '{"type":"simple"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('int-easy-le-podcast-du-voyageur', 'catalog', 'INT', 'easy', array['daily']::text[], 'Le Podcast du Voyageur', 'Les routes sont longues, et la sagesse voyage mieux à plusieurs. Écoute ceux qui savent.', 'Écouter 15 minutes d’un podcast ou d’une conférence instructive.', array['Choisis un sujet qui t’intrigue.', 'Écoute pendant une marche ou un trajet.']::text[], '{"type":"timer","minutes":15}'::jsonb, array['sans matériel', 'moins de 20 min']::text[], true),
('int-easy-le-mot-retrouve', 'catalog', 'INT', 'easy', array['daily']::text[], 'Le Mot Retrouvé', 'Chaque mot oublié est une porte fermée. Les grands lecteurs en rouvrent une par jour.', 'Chercher le sens d’un mot ou d’une expression que tu ne maîtrises pas et l’employer à l’oral ou à l’écrit.', array['Garde une liste de mots à retenir.', 'Utilise-le dans une phrase le jour même.']::text[], '{"type":"simple"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('int-easy-les-fiches-du-bibliothecaire', 'catalog', 'INT', 'easy', array['daily']::text[], 'Les Fiches du Bibliothécaire', 'Un bibliothécaire sait que ce qui se classe se retient. Ta mémoire aime l’ordre.', 'Résumer en 3 phrases ce que tu as appris ou lu aujourd’hui.', array['Utilise tes propres mots.', 'Note-le dans un carnet ou une note.']::text[], '{"type":"simple"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('int-easy-la-carte-du-monde', 'catalog', 'INT', 'easy', array['daily']::text[], 'La Carte du Monde', 'Les cartographes ne dessinaient que ce qu’ils avaient vu. Toi, tu as Internet.', 'Apprendre 3 faits sur un pays, une ville ou une époque que tu connais mal.', array['Cherche des images pour t’en souvenir.', 'Raconte-les à quelqu’un.']::text[], '{"type":"counter","target":3,"unit":"faits"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('int-easy-la-lecon-du-maitre', 'catalog', 'INT', 'easy', array['daily']::text[], 'La Leçon du Maître', 'Les maîtres d’armes enseignent toujours une seule chose par séance. Ils savent que l’esprit retient peu mais bien.', 'Suivre une courte leçon en ligne (10 minutes) sur un sujet qui t’intéresse.', array['Prends des notes pendant la leçon.', 'Refais l’exercice proposé.']::text[], '{"type":"timer","minutes":10}'::jsonb, array['moins de 10 min']::text[], true),
('int-easy-le-calcul-de-tete', 'catalog', 'INT', 'easy', array['daily']::text[], 'Le Calcul de Tête', 'Le marchand perd peu : il compte vite. Tes neurones aussi aiment les chiffres.', 'Faire 10 calculs mentaux sans calculatrice.', array['Invente-toi des petits problèmes.', 'Vérifie ensuite avec la calculatrice.']::text[], '{"type":"counter","target":10,"unit":"calculs"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('int-easy-l-atlas-des-idees', 'catalog', 'INT', 'easy', array['daily']::text[], 'L’Atlas des Idées', 'Les idées ne vivent pas seules : elles s’accrochent les unes aux autres comme des villages sur une carte.', 'Relier deux idées que tu as apprises récemment et noter le lien en une phrase.', array['Pose-toi la question : en quoi sont-elles liées ?', 'Dessine un petit schéma si tu veux.']::text[], '{"type":"simple"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('int-easy-la-chronique-du-jour', 'catalog', 'INT', 'easy', array['daily']::text[], 'La Chronique du Jour', 'Les chroniqueurs écrivaient l’histoire en train de se faire. Lis la tienne avec attention.', 'Lire un article de fond (pas un titre) sur un sujet qui compte pour toi.', array['Choisis une source de qualité.', 'Note ce qui t’a surpris.']::text[], '{"type":"simple"}'::jsonb, array['sans matériel', 'moins de 20 min']::text[], true),
('int-easy-la-memoire-de-l-elephant', 'catalog', 'INT', 'easy', array['daily']::text[], 'La Mémoire de l’Éléphant', 'La mémoire est un muscle. Elle grandit quand on l’interroge.', 'Réciter de mémoire un poème, une citation ou une liste de 5 éléments que tu as appris.', array['Répète avant de dormir.', 'Utilise une image mentale pour chaque élément.']::text[], '{"type":"simple"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('int-easy-la-piece-du-joueur-d-echecs', 'catalog', 'INT', 'easy', array['daily']::text[], 'La Pièce du Joueur d’Échecs', 'Aux échecs, un seul coup suffit parfois à changer l’histoire. Encore faut-il l’avoir vu.', 'Résoudre un problème d’échecs ou jouer une partie rapide.', array['Utilise une application d’entraînement.', 'Cherche le coup avant de jouer.']::text[], '{"type":"simple"}'::jsonb, array['moins de 20 min']::text[], true),
('int-medium-les-runes-oubliees', 'catalog', 'INT', 'medium', array['daily', 'weekly']::text[], 'Les Runes Oubliées', 'Les mages anciens apprenaient une rune par jour. Au bout d’un an, ils parlaient aux dragons.', 'Consacrer 20 minutes à l’apprentissage d’une langue ou d’une compétence (cours, appli, exercices).', array['Fixe-toi un créneau quotidien.', 'Pratique à voix haute.']::text[], '{"type":"timer","minutes":20}'::jsonb, array['langue']::text[], true),
('int-medium-le-chapitre-du-lecteur', 'catalog', 'INT', 'medium', array['daily', 'weekly']::text[], 'Le Chapitre du Lecteur', 'Un lecteur régulier traverse des mondes sans quitter son fauteuil. Voici ton billet pour aujourd’hui.', 'Lire 30 pages ou 30 minutes dans un livre.', array['Éteins les notifications.', 'Lis dans un endroit où tu aimes t’installer.']::text[], '{"type":"timer","minutes":30}'::jsonb, array['sans matériel']::text[], true),
('int-medium-l-apprenti-du-code', 'catalog', 'INT', 'medium', array['daily']::text[], 'L’Apprenti du Code', 'Les sortilèges d’aujourd’hui s’écrivent en lignes. Même les plus puissants ont commencé par une seule.', 'Pratiquer 20 minutes de programmation ou d’un outil numérique que tu veux maîtriser.', array['Résous un petit exercice complet.', 'Termine toujours par quelque chose qui marche.']::text[], '{"type":"timer","minutes":20}'::jsonb, array['numérique']::text[], true),
('int-medium-la-conference-du-soir', 'catalog', 'INT', 'medium', array['weekly']::text[], 'La Conférence du Soir', 'Dans la grande salle, un conférencier parle de ce qu’il aime. Tu y apprends toujours quelque chose.', 'Regarder ou écouter une conférence ou un documentaire de 45 minutes et en noter 5 idées.', array['Prends des notes à la main.', 'Choisis un sujet éloigné de ton quotidien.']::text[], '{"type":"steps","steps":["Choisir le sujet","Regarder en prenant des notes","Résumer en 5 idées"]}'::jsonb, array['sans matériel']::text[], true),
('int-medium-la-partie-de-l-erudit', 'catalog', 'INT', 'medium', array['daily', 'weekly']::text[], 'La Partie de l’Érudit', 'Chaque coup d’échecs est un petit problème que l’on résout en silence.', 'Jouer ou analyser 20 minutes d’échecs, de go ou d’un jeu de stratégie.', array['Analyse une partie après coup.', 'Cherche pourquoi un coup a fonctionné.']::text[], '{"type":"timer","minutes":20}'::jsonb, array['jeu']::text[], true),
('int-medium-le-cours-du-vendredi', 'catalog', 'INT', 'medium', array['weekly']::text[], 'Le Cours du Vendredi', 'Le monastère ouvre ses portes aux curieux. Il suffit de frapper.', 'Suivre un cours en ligne ou en présentiel d’au moins 45 minutes sur un sujet nouveau.', array['Choisis un sujet que tu repousses.', 'Pose au moins une question.']::text[], '{"type":"timer","minutes":45}'::jsonb, array['langue']::text[], true),
('int-medium-le-lexique-du-voyageur', 'catalog', 'INT', 'medium', array['daily', 'weekly']::text[], 'Le Lexique du Voyageur', 'Une langue étrangère est une clé. Plus elle tourne, plus la serrure s’adoucit.', 'Pratiquer 20 minutes une langue étrangère à l’oral ou à l’écrit.', array['Parle seul à voix haute si besoin.', 'Utilise une appli ou un échange avec quelqu’un.']::text[], '{"type":"timer","minutes":20}'::jsonb, array['langue']::text[], true),
('int-medium-la-fiche-de-revision', 'catalog', 'INT', 'medium', array['daily']::text[], 'La Fiche de Révision', 'Retenir, c’est réordonner. Le savant ne mémorise pas, il reconstruit.', 'Faire une fiche de synthèse (schéma, carte mentale ou résumé) sur un sujet que tu étudies.', array['Une page, pas plus.', 'Explique-la à voix haute à quelqu’un d’imaginaire.']::text[], '{"type":"simple"}'::jsonb, array['sans matériel']::text[], true),
('int-medium-l-enquete-du-detective', 'catalog', 'INT', 'medium', array['weekly']::text[], 'L’Enquête du Détective', 'Le détective ne devine pas. Il observe, relie, doute, vérifie.', 'Enquêter sur un sujet qui t’intrigue : lire 3 sources différentes et écrire ce qu’elles ont en commun.', array['Croise des points de vue opposés.', 'Garde un œil critique.']::text[], '{"type":"steps","steps":["Choisir une question","Lire trois sources","Écrire une synthèse"]}'::jsonb, array['sans matériel']::text[], true),
('int-medium-la-dissertation-interieure', 'catalog', 'INT', 'medium', array['daily', 'weekly']::text[], 'La Dissertation Intérieure', 'Un débat sans adversaire est un entraînement royal. Il faut défendre ce que l’on ne pense pas.', 'Écrire 15 minutes en défendant un point de vue opposé au tien sur un sujet.', array['Cherche les meilleurs arguments, pas les plus faciles.', 'Termine par ce que tu as appris.']::text[], '{"type":"timer","minutes":15}'::jsonb, array['sans matériel']::text[], true),
('int-medium-la-bibliotheque-vivante', 'catalog', 'INT', 'medium', array['weekly']::text[], 'La Bibliothèque Vivante', 'Chaque personne est une bibliothèque dont tu n’as lu que la couverture.', 'Poser à quelqu’un des questions sur son métier ou sa passion pendant au moins 20 minutes.', array['Reste curieux, évite de juger.', 'Écoute plus que tu ne parles.']::text[], '{"type":"timer","minutes":20}'::jsonb, array['social']::text[], true),
('int-medium-le-defi-de-logique', 'catalog', 'INT', 'medium', array['daily']::text[], 'Le Défi de Logique', 'Les énigmes du sphinx ont perdu des royaumes. Les tiennes n’ont qu’une récompense : une tête plus claire.', 'Résoudre 3 énigmes, sudokus, jeux de logique ou casse-têtes différents.', array['Passe à l’énigme suivante si tu bloques trop.', 'Reviens-y plus tard.']::text[], '{"type":"counter","target":3,"unit":"énigmes"}'::jsonb, array['jeu']::text[], true),
('int-high-le-codex-acheve', 'catalog', 'INT', 'high', array['weekly', 'monthly']::text[], 'Le Codex Achevé', 'Au fond de la bibliothèque, un codex attend qu’on le termine. Personne ne l’a ouvert depuis des années.', 'Terminer un livre commencé.', array['Fixe-toi un nombre de pages par jour.', 'Lis le soir plutôt que sur ton téléphone.']::text[], '{"type":"simple"}'::jsonb, array['sans matériel']::text[], true),
('int-high-la-semaine-du-disciple', 'catalog', 'INT', 'high', array['weekly']::text[], 'La Semaine du Disciple', 'Les disciples de l’académie étudiaient sept jours d’affilée. Ils appelaient cela un cycle.', 'Étudier un sujet 30 minutes par jour pendant 5 jours.', array['Garde le même créneau.', 'Note à chaque fois un point retenu.']::text[], '{"type":"counter","target":5,"unit":"jours"}'::jsonb, array['langue']::text[], true),
('int-high-le-grand-atelier', 'catalog', 'INT', 'high', array['daily', 'weekly']::text[], 'Le Grand Atelier', 'Le maître d’atelier vérifie ce que l’élève a vraiment compris, pas ce qu’il a lu.', 'Expliquer à quelqu’un (ou à voix haute) un sujet complexe que tu viens d’apprendre, en 10 minutes.', array['Utilise des exemples concrets.', 'Note les points où tu hésites.']::text[], '{"type":"steps","steps":["Préparer mon explication","Expliquer à voix haute","Noter ce qui reste flou"]}'::jsonb, array['social']::text[], true),
('int-high-le-projet-du-compagnon', 'catalog', 'INT', 'high', array['weekly', 'monthly']::text[], 'Le Projet du Compagnon', 'Un compagnon prouve sa valeur en réalisant son projet, pas en le décrivant.', 'Consacrer 3 sessions de 45 minutes à un projet d’apprentissage (code, langue, instrument, recherche).', array['Définis un livrable dès la première session.', 'Garde une trace de chaque avancée.']::text[], '{"type":"counter","target":3,"unit":"sessions"}'::jsonb, array['numérique']::text[], true),
('int-high-la-pile-de-lectures', 'catalog', 'INT', 'high', array['weekly']::text[], 'La Pile de Lectures', 'La pile de livres à lire grandit plus vite que ton temps. Attaque-la proprement.', 'Lire 100 pages dans la semaine.', array['Lis 15 pages par jour.', 'Alterne des genres si tu t’ennuies.']::text[], '{"type":"counter","target":100,"unit":"pages"}'::jsonb, array['sans matériel']::text[], true),
('int-high-le-mois-du-lexique', 'catalog', 'INT', 'high', array['monthly']::text[], 'Le Mois du Lexique', 'Une langue se construit mot après mot. En un mois, un vocabulaire naît.', 'Apprendre 100 mots ou expressions d’une langue étrangère dans le mois.', array['Cinq mots par jour suffisent.', 'Révise les anciens régulièrement.']::text[], '{"type":"counter","target":100,"unit":"mots"}'::jsonb, array['langue']::text[], true),
('int-high-la-synthese-du-savant', 'catalog', 'INT', 'high', array['weekly', 'monthly']::text[], 'La Synthèse du Savant', 'Le savant ne se contente pas d’accumuler. Il écrit ce qu’il a compris pour que les autres comprennent aussi.', 'Écrire une synthèse d’une page sur un sujet que tu as étudié, sans notes.', array['Commence par le plan.', 'Relis-la le lendemain.']::text[], '{"type":"steps","steps":["Étudier le sujet","Écrire le plan","Rédiger la synthèse"]}'::jsonb, array['sans matériel']::text[], true),
('int-high-le-musee-des-savoirs', 'catalog', 'INT', 'high', array['weekly']::text[], 'Le Musée des Savoirs', 'Entre les murs d’un musée, le passé devient lisible. Va y chercher ce que les livres ne disent pas.', 'Visiter un musée, une exposition ou un lieu de culture et noter 5 choses apprises.', array['Prends ton temps devant les pièces qui t’interpellent.', 'Évite de tout lire : choisis.']::text[], '{"type":"simple"}'::jsonb, array['extérieur', 'culture']::text[], true),
('int-high-la-pile-reduite', 'catalog', 'INT', 'high', array['monthly']::text[], 'La Pile Réduite', 'Un livre par semaine, ou presque. Le mois peut changer la manière dont tu vois les choses.', 'Lire 2 livres complets dans le mois.', array['Choisis-en un facile et un exigeant.', 'Lis 20 minutes par jour minimum.']::text[], '{"type":"counter","target":2,"unit":"livres"}'::jsonb, array['sans matériel']::text[], true),
('int-expert-le-grand-uvre-de-l-alchimiste', 'catalog', 'INT', 'expert', array['monthly']::text[], 'Le Grand Œuvre de l’Alchimiste', 'L’alchimiste n’a pas trouvé la pierre philosophale. Il a trouvé mieux : la preuve qu’il pouvait apprendre n’importe quoi.', 'Terminer une formation complète en un mois (cours en ligne, certification, module) et en écrire une synthèse d’une page.', array['Planifie les modules à l’avance.', 'Révise un peu chaque jour.']::text[], '{"type":"steps","steps":["Choisir la formation","Suivre les modules","Passer l’évaluation","Écrire la synthèse"]}'::jsonb, array['numérique']::text[], true),
('int-expert-le-tour-de-babel', 'catalog', 'INT', 'expert', array['monthly', 'epic']::text[], 'Le Tour de Babel', 'On dit qu’il fut un temps où tous parlaient une seule langue. Toi, tu en apprends une deuxième.', 'Atteindre un niveau de conversation de base (A2) dans une langue étrangère : tenir un échange de 10 minutes.', array['Pratique 20 minutes par jour.', 'Trouve un partenaire de conversation.']::text[], '{"type":"steps","steps":["Choisir ma méthode","Pratiquer tous les jours","Tenir une conversation de 10 minutes"]}'::jsonb, array['langue']::text[], true),
('int-expert-la-quete-des-cinq-livres', 'catalog', 'INT', 'expert', array['weekly', 'monthly']::text[], 'La Quête des Cinq Livres', 'Cinq livres sont rangés tout en haut de l’étagère. Personne n’est monté depuis des années.', 'Lire 5 livres dans la période.', array['Choisis-les à l’avance.', 'Lis 40 pages par jour.']::text[], '{"type":"counter","target":5,"unit":"livres"}'::jsonb, array['sans matériel']::text[], true),
('int-expert-le-projet-du-maitre', 'catalog', 'INT', 'expert', array['monthly', 'epic']::text[], 'Le Projet du Maître', 'Le titre de maître se gagne par un ouvrage que l’on peut montrer.', 'Mener à terme un projet d’apprentissage ambitieux (application, mémoire, site, jeu) et le présenter.', array['Découpe en jalons hebdomadaires.', 'Demande un retour avant la fin.']::text[], '{"type":"steps","steps":["Définir le projet","Réaliser la première version","Itérer sur les retours","Présenter le résultat"]}'::jsonb, array['numérique']::text[], true),
('int-expert-le-sceau-de-la-sagesse', 'catalog', 'INT', 'expert', array['monthly']::text[], 'Le Sceau de la Sagesse', 'Trente jours d’étude régulière. Voilà ce qui distingue l’apprenti du bachelier.', 'Étudier un sujet au moins 30 minutes par jour pendant 30 jours.', array['Choisis un sujet qui te passionne.', 'Note tes progrès chaque semaine.']::text[], '{"type":"counter","target":30,"unit":"jours"}'::jsonb, array['langue']::text[], true),
('sag-easy-le-souffle-du-moine', 'catalog', 'SAG', 'easy', array['daily']::text[], 'Le Souffle du Moine', 'Le moine du monastère de Brumeval répète qu’il n’y a rien de plus difficile que de ne rien faire. Vérifie.', 'Méditer 5 minutes, assis, sans téléphone.', array['Concentre-toi sur la sensation de l’air qui entre et sort par le nez.', 'Si ton esprit s’égare, ramène-le sans te juger : c’est l’exercice.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('sag-easy-les-trois-gratitudes', 'catalog', 'SAG', 'easy', array['daily']::text[], 'Les Trois Gratitudes', 'Le voyageur qui compte ses bienfaits marche plus léger. Ils sont toujours plus nombreux qu’il ne le croit.', 'Noter 3 choses pour lesquelles tu es reconnaissant aujourd’hui.', array['Des petites choses suffisent.', 'Sois précis : « le café chaud de 8 h » plutôt que « le café ».']::text[], '{"type":"counter","target":3,"unit":"gratitudes"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('sag-easy-la-respiration-de-l-archer', 'catalog', 'SAG', 'easy', array['daily']::text[], 'La Respiration de l’Archer', 'L’archer inspire, retient, relâche. La flèche part au bon moment, jamais avant.', 'Faire 3 minutes de respiration profonde (4 secondes d’inspiration, 6 d’expiration).', array['Pose une main sur le ventre.', 'Si la tête tourne, reprends un rythme normal.']::text[], '{"type":"timer","minutes":3}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('sag-easy-le-silence-de-la-chapelle', 'catalog', 'SAG', 'easy', array['daily']::text[], 'Le Silence de la Chapelle', 'Dans la chapelle, personne ne parle. Pourtant tout le monde y entend plus qu’ailleurs.', 'Rester 5 minutes sans bruit ni écran, assis ou en marchant lentement.', array['Coupe la musique et les notifications.', 'Écoute les sons qui t’entourent.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('sag-easy-le-regard-du-jardinier', 'catalog', 'SAG', 'easy', array['daily']::text[], 'Le Regard du Jardinier', 'Le jardinier voit pousser ce que les pressés n’aperçoivent jamais. Prends le temps de regarder.', 'Observer pendant 5 minutes quelque chose de vivant : une plante, un arbre, le ciel, un animal.', array['Note trois détails que tu n’avais jamais vus.', 'Pose ton téléphone.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['extérieur', 'moins de 10 min']::text[], true),
('sag-easy-la-porte-de-la-nuit', 'catalog', 'SAG', 'easy', array['daily']::text[], 'La Porte de la Nuit', 'La nuit tombe sur le royaume. Les sages ferment leurs portes avec un rituel, pas avec un écran.', 'Faire un petit rituel avant de dormir (tisane, étirements, lecture, respiration) pendant au moins 5 minutes.', array['Garde le même ordre chaque soir.', 'Baisse les lumières.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['sommeil', 'sans matériel']::text[], true),
('sag-easy-la-pause-du-sage', 'catalog', 'SAG', 'easy', array['daily']::text[], 'La Pause du Sage', 'Le sage sait que l’urgence est souvent un mirage. Il s’arrête avant de répondre.', 'Prendre 3 pauses conscientes de 1 minute dans la journée (respirer, sentir ses pieds, regarder au loin).', array['Mets des rappels discrets.', 'Ferme les yeux si possible.']::text[], '{"type":"counter","target":3,"unit":"pauses"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('sag-easy-la-fenetre-sur-le-ciel', 'catalog', 'SAG', 'easy', array['daily']::text[], 'La Fenêtre sur le Ciel', 'Les astronomes lèvent les yeux avant de prendre la plume. Le ciel n’a jamais manqué d’idées.', 'Regarder le ciel pendant 3 minutes (nuages, étoiles, soleil couchant), sans photo.', array['Sors dehors si tu peux.', 'Observe les changements de couleurs.']::text[], '{"type":"timer","minutes":3}'::jsonb, array['extérieur', 'moins de 10 min']::text[], true),
('sag-easy-le-repas-attentif', 'catalog', 'SAG', 'easy', array['daily']::text[], 'Le Repas Attentif', 'À la table des moines, on mange en silence pour sentir ce que l’on mange.', 'Prendre un repas ou une collation sans écran, en savourant chaque bouchée.', array['Pose les couverts entre les bouchées.', 'Sens les goûts et les textures.']::text[], '{"type":"simple"}'::jsonb, array['alimentation', 'sans matériel']::text[], true),
('sag-easy-la-marche-lente', 'catalog', 'SAG', 'easy', array['daily']::text[], 'La Marche Lente', 'Le pèlerin lent voit plus de pays que le cavalier pressé.', 'Marcher 5 minutes très lentement, en sentant chaque pas.', array['Respire à ton rythme.', 'Regarde devant toi, pas ton téléphone.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['extérieur', 'sans matériel']::text[], true),
('sag-easy-le-point-du-jour', 'catalog', 'SAG', 'easy', array['daily']::text[], 'Le Point du Jour', 'Un capitaine fait le point avant d’appareiller. Toi aussi, regarde où tu en es.', 'Te demander « comment je me sens ? » et nommer ton émotion principale en une phrase.', array['Utilise un mot précis : tendu, curieux, fatigué, serein…', 'Pas de jugement, juste une observation.']::text[], '{"type":"simple"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('sag-easy-l-intention-du-matin', 'catalog', 'SAG', 'easy', array['daily']::text[], 'L’Intention du Matin', 'Un voyageur qui sait où il va marche mieux. Une intention vaut mieux qu’un programme.', 'Écrire une intention pour ta journée en une phrase, dès le matin.', array['Une intention, pas une tâche : « rester calme », « être curieux ».', 'Relis-la à midi.']::text[], '{"type":"simple"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('sag-easy-le-detox-du-soir', 'catalog', 'SAG', 'easy', array['daily']::text[], 'Le Détox du Soir', 'Les chandelles s’éteignent une à une. Les écrans devraient en faire autant.', 'Passer 1 heure sans écran de loisir le soir.', array['Prépare une activité de remplacement.', 'Mets le téléphone en mode avion si besoin.']::text[], '{"type":"simple"}'::jsonb, array['sommeil']::text[], true),
('sag-easy-l-etirement-du-contemplatif', 'catalog', 'SAG', 'easy', array['daily']::text[], 'L’Étirement du Contemplatif', 'Tout se tend en toi. Ouvre, respire, laisse passer.', 'Faire 5 minutes d’étirements doux avec respiration lente.', array['Un étirement à la fois, 30 secondes.', 'Expire dans la tension.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('sag-medium-le-carnet-du-chroniqueur', 'catalog', 'SAG', 'medium', array['daily', 'weekly']::text[], 'Le Carnet du Chroniqueur', 'Les chroniqueurs écrivent l’histoire des rois. Toi, tu écris la tienne, et elle compte autant.', 'Écrire 3 choses vécues aujourd’hui et ce qu’elles t’ont appris.', array['Écris sans te corriger.', 'Pas besoin de belles phrases.']::text[], '{"type":"journal","minChars":50}'::jsonb, array['sans matériel']::text[], true),
('sag-medium-la-meditation-du-moine', 'catalog', 'SAG', 'medium', array['daily', 'weekly']::text[], 'La Méditation du Moine', 'Dix minutes d’immobilité valent mieux que dix heures d’agitation. Le moine le sait depuis toujours.', 'Méditer 10 minutes avec le chronomètre intégré.', array['Assieds-toi dos droit, sans te crisper.', 'Utilise une méditation guidée si tu débutes.']::text[], '{"type":"timer","minutes":10}'::jsonb, array['sans matériel']::text[], true),
('sag-medium-la-promenade-du-contemplatif', 'catalog', 'SAG', 'medium', array['daily']::text[], 'La Promenade du Contemplatif', 'Le contemplatif ne cherche pas la destination. Il marche pour entendre.', 'Faire une promenade de 30 minutes en pleine nature, sans écouteurs.', array['Choisis un parc, un bois, une berge.', 'Garde le téléphone en poche.']::text[], '{"type":"timer","minutes":30}'::jsonb, array['extérieur', 'nature']::text[], true),
('sag-medium-la-soiree-sans-ecran', 'catalog', 'SAG', 'medium', array['weekly']::text[], 'La Soirée sans Écran', 'Dans les auberges d’autrefois, on parlait, on riait, on chantait. Tout cela sans écran.', 'Passer une soirée entière sans écran (télé, jeux, réseaux).', array['Prévois une activité : lecture, jeu de société, cuisine, balade.', 'Préviens ton entourage.']::text[], '{"type":"simple"}'::jsonb, array['détox']::text[], true),
('sag-medium-le-cercle-de-silence', 'catalog', 'SAG', 'medium', array['daily', 'weekly']::text[], 'Le Cercle de Silence', 'Aux heures de l’aube, un cercle se forme dans les montagnes. Personne ne parle, tout le monde entend.', 'Faire 15 minutes de silence complet (méditation, marche lente ou simple présence).', array['Éloigne-toi des bruits quotidiens.', 'Accueille les pensées puis laisse-les passer.']::text[], '{"type":"timer","minutes":15}'::jsonb, array['sans matériel']::text[], true),
('sag-medium-la-lettre-a-soi', 'catalog', 'SAG', 'medium', array['weekly']::text[], 'La Lettre à Soi', 'Les sages écrivaient à leur futur pour se souvenir de ce qu’ils pensaient. Fais-le.', 'Écrire une lettre à toi-même dans un an (ou à toi-même il y a un an).', array['Parle de ce qui compte pour toi aujourd’hui.', 'Conserve-la à un endroit sûr.']::text[], '{"type":"journal","minChars":50}'::jsonb, array['sans matériel']::text[], true),
('sag-medium-le-rituel-du-matin', 'catalog', 'SAG', 'medium', array['daily', 'weekly']::text[], 'Le Rituel du Matin', 'Le chevalier prépare son armure avant de sortir. Prépare ton esprit.', 'Faire une routine de 15 minutes sans écran au réveil (étirements, respiration, écriture, lecture).', array['Garde les mêmes gestes.', 'Prépare tout la veille.']::text[], '{"type":"timer","minutes":15}'::jsonb, array['matin']::text[], true),
('sag-medium-la-nature-en-partage', 'catalog', 'SAG', 'medium', array['daily']::text[], 'La Nature en Partage', 'Les druides disaient que la forêt parle à qui se tait. Écoute-la un peu.', 'Passer 30 minutes dehors dans un espace vert, sans téléphone.', array['Observe les arbres, le sol, les oiseaux.', 'Marche ou assieds-toi, comme tu préfères.']::text[], '{"type":"timer","minutes":30}'::jsonb, array['extérieur', 'nature']::text[], true),
('sag-medium-le-bilan-du-dimanche', 'catalog', 'SAG', 'medium', array['weekly']::text[], 'Le Bilan du Dimanche', 'Chaque semaine, les capitaines relisent leur journal de bord pour corriger le cap.', 'Faire le bilan de ta semaine : trois réussites, trois difficultés, une intention pour la suivante.', array['Prends 15 minutes au calme.', 'Écris-le dans un carnet.']::text[], '{"type":"steps","steps":["Lister mes trois réussites","Lister mes trois difficultés","Choisir une intention"]}'::jsonb, array['sans matériel']::text[], true),
('sag-medium-la-respiration-du-dragon', 'catalog', 'SAG', 'medium', array['daily', 'weekly']::text[], 'La Respiration du Dragon', 'Dans le grimoire des moines, un souffle puissant précède chaque geste juste.', 'Pratiquer 10 minutes de respiration guidée (cohérence cardiaque ou respiration carrée).', array['Utilise un guide audio ou visuel.', 'Respire doucement, sans forcer.']::text[], '{"type":"timer","minutes":10}'::jsonb, array['sans matériel']::text[], true),
('sag-medium-la-journee-de-la-gratitude', 'catalog', 'SAG', 'medium', array['weekly']::text[], 'La Journée de la Gratitude', 'Un cœur reconnaissant voit les mêmes journées avec d’autres yeux.', 'Dire merci à 3 personnes différentes de manière sincère et précise.', array['Cite ce que la personne a fait concrètement.', 'Fais-le en face ou par message.']::text[], '{"type":"counter","target":3,"unit":"personnes"}'::jsonb, array['social']::text[], true),
('sag-medium-la-retraite-d-une-heure', 'catalog', 'SAG', 'medium', array['daily']::text[], 'La Retraite d’une Heure', 'L’ermite s’éloigne le temps d’un feu de camp. Une heure peut suffire à se retrouver.', 'Passer 1 heure seul(e), sans écran ni obligation, à faire une chose qui t’apaise.', array['Prévois-la dans ton agenda.', 'Éloigne-toi des sollicitations.']::text[], '{"type":"timer","minutes":60}'::jsonb, array['détox']::text[], true),
('sag-high-la-retraite-de-l-ermite', 'catalog', 'SAG', 'high', array['weekly']::text[], 'La Retraite de l’Ermite', 'L’ermite ne fuit pas le monde. Il s’en éloigne juste assez pour l’entendre à nouveau.', 'Passer une demi-journée sans réseaux sociaux ni écran de loisir.', array['Préviens ton entourage.', 'Prévois une balade, un livre ou un atelier.']::text[], '{"type":"simple"}'::jsonb, array['détox']::text[], true),
('sag-high-le-cycle-du-moine', 'catalog', 'SAG', 'high', array['weekly', 'monthly']::text[], 'Le Cycle du Moine', 'Une semaine de méditation, et la montagne cesse d’être un obstacle.', 'Méditer 10 minutes par jour pendant 7 jours de suite.', array['Garde le même créneau chaque jour.', 'Utilise un rappel quotidien.']::text[], '{"type":"counter","target":7,"unit":"jours"}'::jsonb, array['sans matériel']::text[], true),
('sag-high-le-carnet-des-sept-jours', 'catalog', 'SAG', 'high', array['weekly']::text[], 'Le Carnet des Sept Jours', 'Sept soirs, sept pages : l’histoire d’une semaine se lit mieux une fois écrite.', 'Écrire dans un journal chaque soir pendant 7 jours.', array['Cinq lignes suffisent.', 'Termine par une chose dont tu es fier.']::text[], '{"type":"counter","target":7,"unit":"jours"}'::jsonb, array['sans matériel']::text[], true),
('sag-high-la-journee-du-silence', 'catalog', 'SAG', 'high', array['daily', 'weekly']::text[], 'La Journée du Silence', 'Un jour entier sans discours inutile : tu en ressortiras avec plus de choses à dire.', 'Passer une demi-journée en silence relatif : parler seulement quand nécessaire, sans écran de loisir.', array['Prévois un moment sans obligation.', 'Écris tes pensées si besoin.']::text[], '{"type":"simple"}'::jsonb, array['détox']::text[], true),
('sag-high-le-cercle-de-la-nature', 'catalog', 'SAG', 'high', array['weekly', 'monthly']::text[], 'Le Cercle de la Nature', 'La forêt n’est pas un décor, c’est un maître. Va la voir régulièrement.', 'Passer au moins 2 heures dans la nature dans la semaine, en une ou plusieurs sorties.', array['Prévois une sortie de week-end.', 'Pose ton téléphone dans le sac.']::text[], '{"type":"counter","target":2,"unit":"heures"}'::jsonb, array['extérieur', 'nature']::text[], true),
('sag-high-le-mois-de-la-gratitude', 'catalog', 'SAG', 'high', array['monthly']::text[], 'Le Mois de la Gratitude', 'Une gratitude par jour, c’est trente raisons de sourire au bout du mois.', 'Noter 3 gratitudes chaque jour pendant 21 jours dans le mois.', array['Fais-le toujours au même moment.', 'Varie les sujets pour ne pas te répéter.']::text[], '{"type":"counter","target":21,"unit":"jours"}'::jsonb, array['sans matériel']::text[], true),
('sag-high-la-semaine-sans-reseaux', 'catalog', 'SAG', 'high', array['weekly']::text[], 'La Semaine Sans Réseaux', 'Les nouvelles viennent à ceux qui les attendent. Les autres découvrent le calme.', 'Passer 5 jours sans réseaux sociaux.', array['Désinstalle les applications le temps du défi.', 'Prévois des occupations pour les moments d’ennui.']::text[], '{"type":"counter","target":5,"unit":"jours"}'::jsonb, array['détox']::text[], true),
('sag-high-le-chemin-interieur', 'catalog', 'SAG', 'high', array['weekly', 'monthly']::text[], 'Le Chemin Intérieur', 'Tous les cartographes ont un blanc sur la carte : leur propre intérieur.', 'Faire 3 sessions d’au moins 20 minutes de journal, de méditation ou de thérapie dans la semaine.', array['Choisis la forme qui te convient.', 'Note ce que tu as découvert.']::text[], '{"type":"counter","target":3,"unit":"sessions"}'::jsonb, array['sans matériel']::text[], true),
('sag-high-la-regularite-du-silence', 'catalog', 'SAG', 'high', array['monthly']::text[], 'La Régularité du Silence', 'Un mois de méditation régulière, et le chaos intérieur ressemble déjà à une rivière.', 'Méditer au moins 15 jours dans le mois.', array['Cinq minutes valent mieux que zéro.', 'Utilise une application ou un guide audio.']::text[], '{"type":"counter","target":15,"unit":"jours"}'::jsonb, array['sans matériel']::text[], true),
('sag-expert-le-pelerinage-interieur', 'catalog', 'SAG', 'expert', array['monthly']::text[], 'Le Pèlerinage Intérieur', 'Certains voyages ne se mesurent pas en lieues. Ils durent une lune et changent celui qui les fait.', '30 jours consécutifs de méditation d’au moins 10 minutes.', array['Choisis un créneau fixe.', 'Si tu manques un jour, reprends sans te juger.']::text[], '{"type":"counter","target":30,"unit":"jours"}'::jsonb, array['sans matériel']::text[], true),
('sag-expert-la-retraite-des-montagnes', 'catalog', 'SAG', 'expert', array['monthly', 'epic']::text[], 'La Retraite des Montagnes', 'Les anciens montaient dans les montagnes pour entendre ce que le vacarme du village cachait.', 'Passer un week-end complet (2 jours) en retraite : nature, silence, sans écran ni réseaux.', array['Prépare le lieu et les repas à l’avance.', 'Prévois des activités simples : marche, lecture, écriture.']::text[], '{"type":"steps","steps":["Choisir le lieu","Préparer l’organisation","Vivre la retraite","Écrire ce que j’en retiens"]}'::jsonb, array['détox', 'nature']::text[], true),
('sag-expert-le-journal-des-trente-soirs', 'catalog', 'SAG', 'expert', array['weekly', 'monthly']::text[], 'Le Journal des Trente Soirs', 'Trente pages pour comprendre un mois. L’écriture régulière est un miroir qui ne ment pas.', 'Tenir un journal pendant 30 jours consécutifs (au moins 5 lignes par jour).', array['Écris à heure fixe.', 'Relis le tout à la fin.']::text[], '{"type":"counter","target":30,"unit":"jours"}'::jsonb, array['sans matériel']::text[], true),
('sag-expert-le-mois-sans-ecran-de-loisir', 'catalog', 'SAG', 'expert', array['monthly', 'epic']::text[], 'Le Mois Sans Écran de Loisir', 'Trente jours sans écran de loisir : un royaume entier se met à exister à nouveau.', 'Passer 30 jours sans réseaux sociaux ni jeux ni streaming (hors travail et contacts).', array['Prévois d’autres occupations.', 'Préviens tes proches.']::text[], '{"type":"counter","target":30,"unit":"jours"}'::jsonb, array['détox']::text[], true),
('sag-expert-l-epreuve-du-silence', 'catalog', 'SAG', 'expert', array['monthly']::text[], 'L’Épreuve du Silence', 'Un jour entier sans parler ni écran, c’est un voyage de mille lieues.', 'Passer une journée entière en silence ou presque, sans écran, dans un lieu calme.', array['Prépare tout la veille.', 'Note tes ressentis à la fin.']::text[], '{"type":"simple"}'::jsonb, array['détox', 'nature']::text[], true),
('cha-easy-la-parole-du-messager', 'catalog', 'CHA', 'easy', array['daily']::text[], 'La Parole du Messager', 'Un messager qui ne porte jamais de nouvelles finit par être oublié. Envoie un pigeon.', 'Envoyer un message sincère à quelqu’un à qui tu n’as pas parlé depuis 2 semaines.', array['Pas besoin d’un long texte : « Je pensais à toi. »', 'Pose une vraie question.']::text[], '{"type":"simple"}'::jsonb, array['sans matériel', 'moins de 10 min']::text[], true),
('cha-easy-le-sourire-du-passant', 'catalog', 'CHA', 'easy', array['daily']::text[], 'Le Sourire du Passant', 'Le sourire d’un étranger est le seul sort qui marche à tous les coups.', 'Sourire et dire bonjour à 3 personnes que tu croises (voisin, commerçant, passant).', array['Regarde dans les yeux.', 'Reste naturel.']::text[], '{"type":"counter","target":3,"unit":"personnes"}'::jsonb, array['social', 'sans matériel']::text[], true),
('cha-easy-la-louange-du-barde', 'catalog', 'CHA', 'easy', array['daily']::text[], 'La Louange du Barde', 'Les bardes chantent les exploits des autres. Ils savent que la reconnaissance ouvre toutes les portes.', 'Faire un compliment sincère et précis à quelqu’un.', array['Cite quelque chose de concret.', 'Dis-le en face si possible.']::text[], '{"type":"simple"}'::jsonb, array['social', 'sans matériel']::text[], true),
('cha-easy-le-merci-du-voyageur', 'catalog', 'CHA', 'easy', array['daily']::text[], 'Le Merci du Voyageur', 'Une route est plus douce quand on remercie ceux qui l’entretiennent.', 'Remercier chaleureusement quelqu’un qui t’a rendu service, même un petit.', array['Dis ce que ça a changé pour toi.', 'Pas de « merci » automatique : mets-y du sens.']::text[], '{"type":"simple"}'::jsonb, array['social', 'moins de 10 min']::text[], true),
('cha-easy-l-oreille-du-confident', 'catalog', 'CHA', 'easy', array['daily']::text[], 'L’Oreille du Confident', 'Le confident du roi ne parle pas beaucoup. Mais tout le monde vient le voir.', 'Écouter quelqu’un pendant 5 minutes sans l’interrompre ni donner de conseil.', array['Reformule ce que tu as compris.', 'Pose le téléphone.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['social', 'sans matériel']::text[], true),
('cha-easy-le-petit-service', 'catalog', 'CHA', 'easy', array['daily']::text[], 'Le Petit Service', 'Les compagnons d’aventure se reconnaissent à leurs petits gestes, pas à leurs grands discours.', 'Rendre un petit service à quelqu’un sans qu’il l’ait demandé.', array['Observe ce dont l’autre a besoin.', 'Ne cherche pas de reconnaissance.']::text[], '{"type":"simple"}'::jsonb, array['social', 'sans matériel']::text[], true),
('cha-easy-la-photo-partagee', 'catalog', 'CHA', 'easy', array['daily']::text[], 'La Photo Partagée', 'Un souvenir partagé est un souvenir doublé.', 'Envoyer à un proche une photo ou un message qui lui rappelle un bon moment ensemble.', array['Ajoute un mot personnel.', 'Choisis quelqu’un à qui tu penses souvent.']::text[], '{"type":"simple"}'::jsonb, array['social', 'moins de 10 min']::text[], true),
('cha-easy-la-voix-d-un-ami', 'catalog', 'CHA', 'easy', array['daily']::text[], 'La Voix d’un Ami', 'Un appel vaut mille messages. Tes amis le savent même s’ils ne le disent pas.', 'Appeler un proche pour prendre des nouvelles (5 minutes suffisent).', array['Choisis quelqu’un à qui tu n’as pas parlé depuis longtemps.', 'Prépare une question ouverte.']::text[], '{"type":"timer","minutes":5}'::jsonb, array['social']::text[], true),
('cha-easy-la-question-qui-ouvre', 'catalog', 'CHA', 'easy', array['daily']::text[], 'La Question qui Ouvre', 'Les bonnes questions sont des clés. Elles ouvrent des portes que les réponses ne font que fermer.', 'Poser une question ouverte à quelqu’un que tu connais peu (collègue, voisin, camarade).', array['« Qu’est-ce qui te plaît le plus dans… ? »', 'Écoute la réponse jusqu’au bout.']::text[], '{"type":"simple"}'::jsonb, array['social', 'moins de 10 min']::text[], true),
('cha-easy-le-c-ur-du-village', 'catalog', 'CHA', 'easy', array['daily']::text[], 'Le Cœur du Village', 'Un village où l’on se salue est un village où l’on vit bien.', 'Prendre des nouvelles d’un voisin, d’un collègue ou d’un proche en lui posant une vraie question.', array['Souviens-toi de ce qu’il t’a dit la dernière fois.', 'Laisse-lui le temps de répondre.']::text[], '{"type":"simple"}'::jsonb, array['social', 'moins de 10 min']::text[], true),
('cha-easy-le-pont-entre-deux-rives', 'catalog', 'CHA', 'easy', array['daily']::text[], 'Le Pont Entre Deux Rives', 'Les bâtisseurs de ponts rapprochent les rives que l’eau sépare.', 'Présenter deux personnes qui pourraient s’apprécier ou se rendre service.', array['Explique en une phrase pourquoi.', 'Laisse-les poursuivre sans toi.']::text[], '{"type":"simple"}'::jsonb, array['social']::text[], true),
('cha-easy-l-ecrit-du-troubadour', 'catalog', 'CHA', 'easy', array['daily']::text[], 'L’Écrit du Troubadour', 'Une lettre écrite à la main a plus de poids qu’un message. Elle prend le temps du cœur.', 'Écrire un petit mot à la main à quelqu’un (carte, post-it, lettre).', array['Trois phrases suffisent.', 'Glisse-le dans un sac ou une boîte aux lettres.']::text[], '{"type":"simple"}'::jsonb, array['social', 'moins de 10 min']::text[], true),
('cha-easy-le-pardon-du-sage', 'catalog', 'CHA', 'easy', array['daily']::text[], 'Le Pardon du Sage', 'Un sage ne garde pas de rancune. Il sait qu’un cœur léger marche plus loin.', 'Écrire ou formuler à voix haute un pardon (envers toi ou quelqu’un d’autre) pour une petite rancune.', array['Commence par un petit sujet.', 'Tu n’as pas besoin de l’envoyer.']::text[], '{"type":"simple"}'::jsonb, array['sans matériel']::text[], true),
('cha-easy-la-ronde-des-prenoms', 'catalog', 'CHA', 'easy', array['daily']::text[], 'La Ronde des Prénoms', 'Retenir un prénom, c’est déjà rendre hommage à quelqu’un.', 'Apprendre et utiliser le prénom d’une personne que tu croises souvent sans la connaître.', array['Demande-le simplement.', 'Répète-le dans la conversation.']::text[], '{"type":"simple"}'::jsonb, array['social', 'moins de 10 min']::text[], true),
('cha-medium-le-banquet-des-allies', 'catalog', 'CHA', 'medium', array['weekly']::text[], 'Le Banquet des Alliés', 'Les alliances ne se scellent pas par courrier. Elles se scellent autour d’une table.', 'Partager un repas ou un café avec quelqu’un, téléphone rangé.', array['Propose un lieu simple.', 'Reste présent pendant toute la rencontre.']::text[], '{"type":"simple"}'::jsonb, array['social']::text[], true),
('cha-medium-la-visite-du-troubadour', 'catalog', 'CHA', 'medium', array['daily', 'weekly']::text[], 'La Visite du Troubadour', 'Le troubadour va de ville en ville. Chaque rencontre est une chanson.', 'Rendre visite ou appeler un proche pour passer au moins 30 minutes ensemble.', array['Prévois-le à l’avance.', 'Choisis un moment sans pression.']::text[], '{"type":"timer","minutes":30}'::jsonb, array['social']::text[], true),
('cha-medium-la-lettre-retrouvee', 'catalog', 'CHA', 'medium', array['weekly']::text[], 'La Lettre Retrouvée', 'On retrouve toujours dans un vieux tiroir un nom qu’on aurait dû garder.', 'Contacter un ancien ami ou collègue perdu de vue et proposer de se revoir.', array['Commence par un souvenir commun.', 'Ne t’excuse pas pour l’absence.']::text[], '{"type":"simple"}'::jsonb, array['social']::text[], true),
('cha-medium-l-offrande-du-marchand', 'catalog', 'CHA', 'medium', array['daily']::text[], 'L’Offrande du Marchand', 'Le meilleur cadeau n’est pas le plus cher, mais celui qui montre qu’on a écouté.', 'Offrir un petit cadeau ou une attention personnalisée à quelqu’un (fait maison, livre, mot).', array['Pense à ce qu’il aime.', 'Remets-le en main propre si possible.']::text[], '{"type":"simple"}'::jsonb, array['social']::text[], true),
('cha-medium-le-cercle-de-parole', 'catalog', 'CHA', 'medium', array['daily', 'weekly']::text[], 'Le Cercle de Parole', 'Dans la grande salle, chacun parle à son tour. L’écoute est un art qui se partage.', 'Participer activement à une discussion de groupe en prenant la parole au moins 2 fois.', array['Prépare une idée avant d’y aller.', 'Écoute avant de répondre.']::text[], '{"type":"counter","target":2,"unit":"prises de parole"}'::jsonb, array['social']::text[], true),
('cha-medium-l-aide-du-compagnon', 'catalog', 'CHA', 'medium', array['weekly']::text[], 'L’Aide du Compagnon', 'Aucun héros n’a vaincu un dragon seul. Les meilleurs savent demander de l’aide.', 'Demander de l’aide à quelqu’un pour quelque chose que tu repoussais, et le remercier.', array['Sois précis dans ta demande.', 'Propose un échange de service.']::text[], '{"type":"simple"}'::jsonb, array['social']::text[], true),
('cha-medium-la-mission-du-benevole', 'catalog', 'CHA', 'medium', array['daily', 'weekly']::text[], 'La Mission du Bénévole', 'Les villages se bâtissent à la force des bras de ceux qui donnent leur temps.', 'Donner 30 minutes de ton temps à quelqu’un ou à une cause (aide à un voisin, association, famille).', array['Choisis un service concret.', 'Demande ce dont la personne a vraiment besoin.']::text[], '{"type":"timer","minutes":30}'::jsonb, array['social']::text[], true),
('cha-medium-la-table-ouverte', 'catalog', 'CHA', 'medium', array['weekly']::text[], 'La Table Ouverte', 'Ouvrir sa table, c’est ouvrir son village.', 'Inviter quelqu’un chez toi pour un repas ou un café.', array['Prévois quelque chose de simple.', 'Dis-lui que tu as pensé à lui.']::text[], '{"type":"simple"}'::jsonb, array['social', 'cuisine']::text[], true),
('cha-medium-le-cercle-rapproche', 'catalog', 'CHA', 'medium', array['daily']::text[], 'Le Cercle Rapproché', 'Les amis proches sont les piliers d’un royaume. Entretiens-les.', 'Passer 20 minutes de qualité avec un proche (jeu, discussion, promenade).', array['Garde ton téléphone loin.', 'Pose une question qui compte.']::text[], '{"type":"timer","minutes":20}'::jsonb, array['social']::text[], true),
('cha-medium-la-parole-de-paix', 'catalog', 'CHA', 'medium', array['daily', 'weekly']::text[], 'La Parole de Paix', 'Un conflit ancien pèse plus lourd que ses causes. Un mot peut le soulever.', 'Désamorcer une tension ou une petite dispute en proposant une discussion calme.', array['Commence par ce que tu ressens.', 'Écoute sans te défendre.']::text[], '{"type":"simple"}'::jsonb, array['social']::text[], true),
('cha-medium-le-rire-du-banquet', 'catalog', 'CHA', 'medium', array['weekly']::text[], 'Le Rire du Banquet', 'Les festins du roi sont connus pour leurs rires plus que pour leurs plats.', 'Organiser un moment convivial (jeu, apéritif, sortie) avec au moins 3 personnes.', array['Choisis une activité simple.', 'Invite une personne qui se sent isolée.']::text[], '{"type":"simple"}'::jsonb, array['social']::text[], true),
('cha-medium-la-demande-du-courageux', 'catalog', 'CHA', 'medium', array['daily', 'weekly']::text[], 'La Demande du Courageux', 'Qui ne demande rien n’obtient rien. Mais demander demande de l’humilité.', 'Faire une demande à laquelle tu n’oses pas répondre toi-même (retour, conseil, feedback sur ton travail).', array['Formule-la clairement.', 'Remercie, quelle que soit la réponse.']::text[], '{"type":"simple"}'::jsonb, array['social']::text[], true),
('cha-high-la-harangue-du-heraut', 'catalog', 'CHA', 'high', array['weekly']::text[], 'La Harangue du Héraut', 'Le héraut tremble avant chaque proclamation. Puis il ouvre la bouche, et la place se tait.', 'Prendre la parole en public ou en réunion pour défendre une idée ou présenter un sujet.', array['Prépare 3 idées maximum.', 'Parle lentement.']::text[], '{"type":"simple"}'::jsonb, array['social']::text[], true),
('cha-high-le-reseau-du-marchand', 'catalog', 'CHA', 'high', array['weekly', 'monthly']::text[], 'Le Réseau du Marchand', 'Une guilde forte est faite de contacts autant que de talents.', 'Rencontrer 3 nouvelles personnes dans ton domaine ou tes centres d’intérêt (événement, club, en ligne).', array['Prépare une présentation d’une phrase.', 'Échange tes coordonnées et donne des nouvelles.']::text[], '{"type":"counter","target":3,"unit":"personnes"}'::jsonb, array['social']::text[], true),
('cha-high-les-trois-appels', 'catalog', 'CHA', 'high', array['weekly']::text[], 'Les Trois Appels', 'Trois voix amies valent plus que mille inconnus.', 'Appeler 3 proches différents dans la semaine, pour au moins 10 minutes chacun.', array['Planifie les appels sur 3 jours.', 'Pose des questions sur eux avant de parler de toi.']::text[], '{"type":"counter","target":3,"unit":"appels"}'::jsonb, array['social']::text[], true),
('cha-high-le-mentor-rencontre', 'catalog', 'CHA', 'high', array['weekly', 'monthly']::text[], 'Le Mentor Rencontré', 'Les grandes histoires ont presque toujours un mentor. Va trouver le tien.', 'Demander conseil à quelqu’un que tu admires ou qui a l’expérience d’un sujet qui te préoccupe, et noter ce que tu retiens.', array['Prépare 3 questions précises.', 'Remercie par écrit ensuite.']::text[], '{"type":"steps","steps":["Choisir la personne","La contacter","Échanger avec elle","Noter ce que je retiens"]}'::jsonb, array['social']::text[], true),
('cha-high-le-diner-des-compagnons', 'catalog', 'CHA', 'high', array['daily', 'weekly']::text[], 'Le Dîner des Compagnons', 'Un repas qui rassemble est un acte d’amitié que l’on n’oublie pas.', 'Réunir 3 personnes ou plus autour d’un repas, et y participer vraiment.', array['Planifie une semaine avant.', 'Répartis les plats entre les invités.']::text[], '{"type":"simple"}'::jsonb, array['social', 'cuisine']::text[], true),
('cha-high-le-mois-de-la-generosite', 'catalog', 'CHA', 'high', array['monthly']::text[], 'Le Mois de la Générosité', 'La générosité est un muscle : on la sent plus à mesure qu’on la travaille.', 'Faire un geste de générosité (temps, aide, don) au moins 10 fois dans le mois.', array['Garde une liste.', 'Commence petit et varie.']::text[], '{"type":"counter","target":10,"unit":"gestes"}'::jsonb, array['social']::text[], true),
('cha-high-la-rencontre-inconnue', 'catalog', 'CHA', 'high', array['weekly']::text[], 'La Rencontre Inconnue', 'Au bout du chemin, il y a toujours un voyageur que l’on n’attendait pas.', 'Engager une vraie conversation avec quelqu’un que tu ne connais pas (événement, voisin, club).', array['Commence par une question simple.', 'Reste dix minutes minimum.']::text[], '{"type":"steps","steps":["Aller vers la personne","Ouvrir la conversation","Échanger au moins 10 minutes"]}'::jsonb, array['social']::text[], true),
('cha-high-la-voix-du-conteur', 'catalog', 'CHA', 'high', array['weekly', 'monthly']::text[], 'La Voix du Conteur', 'Une histoire bien racontée traverse les générations. Un récit sincère fait tomber les barrières.', 'Raconter une histoire personnelle devant au moins 3 personnes.', array['Choisis une histoire courte avec un début et une fin.', 'Parle de ce qui t’a touché.']::text[], '{"type":"simple"}'::jsonb, array['social']::text[], true),
('cha-high-les-dix-messages', 'catalog', 'CHA', 'high', array['monthly']::text[], 'Les Dix Messages', 'Dix personnes que l’on a oubliées de contacter. Le mois est parfait pour y remédier.', 'Renouer avec 10 personnes (message, appel ou rencontre) dans le mois.', array['Fais une liste dès le début.', 'Un message par jour suffit.']::text[], '{"type":"counter","target":10,"unit":"personnes"}'::jsonb, array['social']::text[], true),
('cha-expert-le-conseil-des-seigneurs', 'catalog', 'CHA', 'expert', array['monthly']::text[], 'Le Conseil des Seigneurs', 'Au Conseil, une seule voix peut faire basculer le royaume. Encore faut-il qu’elle se lève.', 'Organiser et animer un événement (soirée, atelier, partie de JDR) pour au moins 5 personnes.', array['Prévois l’invitation 2 semaines avant.', 'Prépare un déroulé simple.']::text[], '{"type":"steps","steps":["Choisir l’événement","Inviter et organiser","Animer l’événement","Faire le bilan"]}'::jsonb, array['social']::text[], true),
('cha-expert-le-grand-rassemblement', 'catalog', 'CHA', 'expert', array['monthly', 'epic']::text[], 'Le Grand Rassemblement', 'Les fêtes du village sont tenues par ceux qui les imaginent. Imagine la tienne.', 'Organiser un rassemblement pour au moins 15 personnes (fête de quartier, tournoi, repas partagé).', array['Délègue des responsabilités.', 'Prépare un plan B en cas de météo.']::text[], '{"type":"steps","steps":["Définir l’événement","Réserver le lieu","Inviter les participants","Animer l’événement","Remercier tout le monde"]}'::jsonb, array['social']::text[], true),
('cha-expert-la-mission-solidaire', 'catalog', 'CHA', 'expert', array['weekly', 'monthly']::text[], 'La Mission Solidaire', 'Il y a des royaumes entiers qui attendent qu’on leur tende la main.', 'Participer à une action solidaire ou bénévole d’au moins 3 heures (association, aide à des voisins).', array['Choisis une cause qui te parle.', 'Inscris-toi à l’avance.']::text[], '{"type":"steps","steps":["Choisir l’action","M’inscrire","Participer","Noter ce que j’en retiens"]}'::jsonb, array['social']::text[], true),
('cha-expert-le-discours-du-couronnement', 'catalog', 'CHA', 'expert', array['monthly', 'epic']::text[], 'Le Discours du Couronnement', 'Un discours sincère devant ceux qu’on aime marque plus qu’une couronne.', 'Préparer et prononcer un discours devant un groupe de 10 personnes ou plus (mariage, anniversaire, remise de prix).', array['Raconte une anecdote vraie.', 'Répète à voix haute trois fois.']::text[], '{"type":"steps","steps":["Écrire mon discours","Le répéter","Le prononcer"]}'::jsonb, array['social']::text[], true),
('cha-expert-la-guilde-que-l-on-fonde', 'catalog', 'CHA', 'expert', array['monthly']::text[], 'La Guilde que l’on Fonde', 'Toute guilde a un fondateur qui s’est dit un jour : pourquoi pas nous ?', 'Créer un groupe, un club ou une communauté (sportif, lecture, jeux, entraide) et organiser la première rencontre.', array['Définis un objectif simple.', 'Invite au moins 5 personnes.']::text[], '{"type":"steps","steps":["Définir le projet du groupe","Inviter les premiers membres","Organiser la première rencontre"]}'::jsonb, array['social']::text[], true)
